-- Additional migration; the frozen schema-control release remains unchanged.
create schema if not exists demo_desktop;
revoke all on schema demo_desktop from public,anon,authenticated,service_role;
do $$begin
 if not exists(select from pg_roles where rolname='demo_desktop_writer') then
  create role demo_desktop_writer nologin nosuperuser nocreatedb nocreaterole noinherit noreplication nobypassrls;
 end if;
end $$;
grant demo_desktop_writer to postgres;
alter table public.demo_catalogs add column if not exists desktop_shared boolean not null default false;
create table if not exists demo_desktop.companies (
 owner_id uuid not null,workspace_id uuid not null,active boolean not null default false,
 revision bigint not null default 0 check(revision>=0),source_revision text,source_sha256 text,
 primary key(owner_id,workspace_id),foreign key(owner_id,workspace_id) references public.demo_catalogs(owner_id,workspace_id)
);
create table if not exists demo_desktop.customers (
 owner_id uuid not null,workspace_id uuid not null,id bigint not null check(id between 1 and 9007199254740991),
 version bigint not null default 1 check(version>=1),data jsonb not null check(jsonb_typeof(data)='object'),
 primary key(owner_id,workspace_id,id),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
create table if not exists demo_desktop.graves (
 owner_id uuid not null,workspace_id uuid not null,id bigint not null check(id between 1 and 9007199254740991),
 customer_id bigint,version bigint not null default 1 check(version>=1),data jsonb not null check(jsonb_typeof(data)='object'),
 primary key(owner_id,workspace_id,id),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id),
 foreign key(owner_id,workspace_id,customer_id) references demo_desktop.customers(owner_id,workspace_id,id)
);
create table if not exists demo_desktop.payments (
 owner_id uuid not null,workspace_id uuid not null,id bigint not null check(id between 1 and 9007199254740991),
 grave_id bigint not null,year integer not null check(year between 1 and 9999),kind text not null default 'annual',
 amount bigint not null check(amount between 0 and 9007199254740991),data jsonb not null default '{}' check(jsonb_typeof(data)='object'),
 primary key(owner_id,workspace_id,id),unique(owner_id,workspace_id,grave_id,year,kind),
 foreign key(owner_id,workspace_id,grave_id) references demo_desktop.graves(owner_id,workspace_id,id)
);
create table if not exists demo_desktop.annual_work (
 owner_id uuid not null,workspace_id uuid not null,id uuid not null,year integer not null check(year between 1 and 9999),
 customer_id bigint not null,grave_id bigint,status text not null check(status in ('uncontacted','proceed','declined')),
 version bigint not null default 1,deleted_at text,data jsonb not null default '{}' check(jsonb_typeof(data)='object'),
 primary key(owner_id,workspace_id,id),unique(owner_id,workspace_id,year,customer_id),
 foreign key(owner_id,workspace_id,customer_id) references demo_desktop.customers(owner_id,workspace_id,id),
 foreign key(owner_id,workspace_id,grave_id) references demo_desktop.graves(owner_id,workspace_id,id)
);
create table if not exists demo_desktop.work_rows (
 owner_id uuid not null,workspace_id uuid not null,key text not null,data jsonb not null,
 primary key(owner_id,workspace_id,key),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
create table if not exists demo_desktop.locations (
 owner_id uuid not null,workspace_id uuid not null,grave_id bigint not null,data jsonb not null,
 primary key(owner_id,workspace_id,grave_id),foreign key(owner_id,workspace_id,grave_id) references demo_desktop.graves(owner_id,workspace_id,id)
);
create table if not exists demo_desktop.earth_links (
 owner_id uuid not null,workspace_id uuid not null,grave_id bigint not null,version_id uuid,data jsonb not null,
 primary key(owner_id,workspace_id,grave_id),foreign key(owner_id,workspace_id,grave_id) references demo_desktop.graves(owner_id,workspace_id,id)
);
create table if not exists demo_desktop.id_counters (
 owner_id uuid not null,workspace_id uuid not null,name text not null check(name in ('customers','graves','payments')),high_water bigint not null check(high_water between 0 and 9007199254740991),
 primary key(owner_id,workspace_id,name),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
create table if not exists demo_desktop.requests (
 owner_id uuid not null,workspace_id uuid not null,actor_id uuid not null,request_id uuid not null,
 session_id uuid not null,input_sha text not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,workspace_id,actor_id,request_id),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
do $$declare t text;begin
 foreach t in array array['companies','customers','graves','payments','annual_work','work_rows','locations','earth_links','id_counters','requests'] loop
  execute format('alter table demo_desktop.%I enable row level security',t);
  execute format('revoke all on demo_desktop.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on demo_desktop.%I to demo_desktop_writer',t);
  execute format('drop policy if exists projection_writer on demo_desktop.%I',t);
  execute format('create policy projection_writer on demo_desktop.%I for all to demo_desktop_writer using(true) with check(true)',t);
 end loop;
end $$;
grant usage on schema demo_desktop to demo_desktop_writer;
grant update(revision) on demo_desktop.companies to demo_desktop_writer;
grant select,insert,update on public.demo_catalogs,public.demo_map_snapshots to demo_desktop_writer;
drop policy if exists desktop_projection_writer on public.demo_catalogs;
create policy desktop_projection_writer on public.demo_catalogs for all to demo_desktop_writer using(true) with check(true);
drop policy if exists desktop_projection_writer on public.demo_map_snapshots;
create policy desktop_projection_writer on public.demo_map_snapshots for all to demo_desktop_writer using(true) with check(true);

create or replace function demo_desktop.fail(p_code text) returns void language plpgsql set search_path='' as $$
begin raise exception '%',p_code using errcode='P0001',hint=p_code;end $$;
create or replace function demo_desktop.auth_session() returns uuid language plpgsql stable security definer set search_path='' as $$declare sid text:=auth.jwt()->>'session_id';begin
 if sid is null or sid!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' or not exists(select from auth.sessions where id=sid::uuid and user_id=auth.uid()) then perform demo_desktop.fail('access-denied');end if;return sid::uuid;
end $$;
create or replace function demo_desktop.assert_actor(p_workspace uuid) returns uuid language plpgsql stable security definer set search_path='' as $$declare m public.demo_members;actor uuid:=auth.uid();begin
 perform demo_desktop.auth_session();
 select * into m from public.demo_members where user_id=actor;
 if found then
  if not m.active or m.role<>'master' or m.workspace_id<>p_workspace then perform demo_desktop.fail('access-denied');end if;return m.owner_id;
 end if;
 if not exists(select from public.demo_catalogs where owner_id=actor and workspace_id=p_workspace) then perform demo_desktop.fail('access-denied');end if;return actor;
end $$;
create or replace function demo_desktop.lock_actor(p_workspace uuid,p_owner uuid) returns void language plpgsql security definer set search_path='' as $$declare m public.demo_members;actor uuid:=auth.uid();sid uuid:=demo_desktop.auth_session();begin
 perform 1 from auth.sessions where id=sid and user_id=actor for key share;
 if not found then perform demo_desktop.fail('access-denied');end if;
 select * into m from public.demo_members where user_id=actor for share;
 if found then
  if not m.active or m.role<>'master' or m.workspace_id<>p_workspace or m.owner_id<>p_owner then perform demo_desktop.fail('access-denied');end if;
 elsif actor is distinct from p_owner then perform demo_desktop.fail('access-denied');end if;
end $$;
create or replace function demo_desktop.lock_company(p_owner uuid,p_workspace uuid) returns void
language plpgsql set search_path='' as $$begin
 -- NO KEY UPDATE is compatible with event FK key-share locks; all writers take it first.
 perform 1 from public.demo_catalogs where owner_id=p_owner and workspace_id=p_workspace for no key update;
 perform 1 from demo_desktop.companies where owner_id=p_owner and workspace_id=p_workspace and active for update;
 if not found then perform demo_desktop.fail('not-shared');end if;
end $$;
create or replace function demo_desktop.next_id(p_owner uuid,p_workspace uuid,p_name text) returns bigint
language plpgsql set search_path='' as $$declare maximum bigint;result bigint;begin
 if p_name not in ('customers','graves','payments') then perform demo_desktop.fail('invalid-input');end if;
 execute format('select coalesce(max(id),0) from demo_desktop.%I where owner_id=$1 and workspace_id=$2',p_name) into maximum using p_owner,p_workspace;
 insert into demo_desktop.id_counters(owner_id,workspace_id,name,high_water) values(p_owner,p_workspace,p_name,maximum)
 on conflict(owner_id,workspace_id,name) do update set high_water=greatest(demo_desktop.id_counters.high_water,excluded.high_water);
 update demo_desktop.id_counters set high_water=high_water+1 where owner_id=p_owner and workspace_id=p_workspace and name=p_name and high_water<9007199254740991 returning high_water into result;
 if result is null then perform demo_desktop.fail('invalid-input');end if;return result;
end $$;
create or replace function demo_desktop.text_value(p_input jsonb,p_key text,p_limit integer default 10000) returns text
language plpgsql immutable set search_path='' as $$declare value text;begin
 if not p_input ? p_key then return null;end if;
 if jsonb_typeof(p_input->p_key) is distinct from 'string' or char_length(p_input->>p_key)>p_limit then perform demo_desktop.fail('invalid-input');end if;
 value:=nullif(btrim(normalize(p_input->>p_key,NFC)),'');return value;
end $$;
create or replace function demo_desktop.number_value(p_input jsonb,p_key text,p_decimal boolean default false) returns numeric
language plpgsql immutable set search_path='' as $$declare value text;n numeric;begin
 value:=replace(demo_desktop.text_value(p_input,p_key),',','');if value is null then return null;end if;
 if value !~ (case when p_decimal then '^[0-9]+(\.[0-9]+)?$' else '^[0-9]+$' end) then perform demo_desktop.fail('invalid-input');end if;
 n:=value::numeric;if n>9007199254740991 then perform demo_desktop.fail('invalid-input');end if;return n;
end $$;
create or replace function demo_desktop.assert_editable(p_owner uuid,p_workspace uuid,p_session uuid,p_customer bigint,p_token uuid default null) returns void
language plpgsql set search_path='' as $$begin
 if not exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=p_customer) then perform demo_desktop.fail('conflict');end if;
end $$;
create or replace function demo_desktop.entity_revision(p_owner uuid,p_workspace uuid,p_customer bigint,p_grave bigint) returns text
language plpgsql stable set search_path='' as $$declare parent bigint;v bigint;begin
 if p_grave is not null then
  select customer_id,version into parent,v from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=p_grave;
  if not found or parent is distinct from p_customer then perform demo_desktop.fail('conflict');end if;
 end if;
 if p_customer is not null then
  select version into v from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=p_customer;
  if not found then perform demo_desktop.fail('conflict');end if;
  return 'customer:'||p_customer||':'||v;
 end if;
 if p_grave is null then perform demo_desktop.fail('invalid-input');end if;
 return 'grave:'||p_grave||':'||v;
end $$;
create or replace function demo_desktop.bump(p_owner uuid,p_workspace uuid,p_customer bigint,p_grave bigint) returns void
language plpgsql set search_path='' as $$begin
 if p_customer is not null then update demo_desktop.customers set version=version+1 where owner_id=p_owner and workspace_id=p_workspace and id=p_customer;
 else update demo_desktop.graves set version=version+1 where owner_id=p_owner and workspace_id=p_workspace and id=p_grave;end if;
end $$;

-- Invoker identity must be retained: postgres-owned legacy RPCs are not projection writers.
create or replace function public.demo_desktop_catalog_gate() returns trigger language plpgsql set search_path='' as $$begin
 if current_user<>'demo_desktop_writer' and (new.desktop_shared or (tg_op='UPDATE' and old.desktop_shared)) then perform public.demo_desktop_write_denied();end if;
 return new;
end $$;
create or replace function public.demo_desktop_write_denied() returns void language plpgsql set search_path='' as $$begin
 raise exception 'Shared desktop projection cannot be overwritten' using errcode='P0001',hint='not-shared';
end $$;
create or replace function public.demo_desktop_map_gate() returns trigger language plpgsql set search_path='' as $$begin
 if current_user<>'demo_desktop_writer' and exists(select from public.demo_catalogs where owner_id=new.owner_id and workspace_id=new.workspace_id and desktop_shared) then perform public.demo_desktop_write_denied();end if;
 return new;
end $$;
drop trigger if exists desktop_catalog_gate on public.demo_catalogs;
create trigger desktop_catalog_gate before insert or update on public.demo_catalogs for each row execute function public.demo_desktop_catalog_gate();
drop trigger if exists desktop_map_gate on public.demo_map_snapshots;
create trigger desktop_map_gate before insert or update on public.demo_map_snapshots for each row execute function public.demo_desktop_map_gate();
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;
revoke all on function public.demo_desktop_write_denied(),public.demo_desktop_catalog_gate(),public.demo_desktop_map_gate() from public,anon;
grant execute on function public.demo_desktop_write_denied() to authenticated,service_role,demo_desktop_writer;

create table if not exists demo_desktop.work_routes(
 owner_id uuid not null,workspace_id uuid not null,id uuid not null default gen_random_uuid(),year integer not null check(year between 1 and 9999),
 identity jsonb not null,version bigint not null default 1,data jsonb not null,
 primary key(owner_id,workspace_id,id),unique(owner_id,workspace_id,year,identity),
 foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
alter table demo_desktop.work_routes enable row level security;
revoke all on demo_desktop.work_routes from public,anon,authenticated,service_role;
grant select on demo_desktop.work_routes to demo_desktop_writer;
drop policy if exists projection_writer on demo_desktop.work_routes;
create policy projection_writer on demo_desktop.work_routes for select to demo_desktop_writer using(true);
create or replace function demo_desktop.route_selection(p_region text) returns jsonb language plpgsql immutable set search_path='' as $$
declare items jsonb;item jsonb;begin
 if p_region is null or p_region='' or p_region='*' or length(p_region)>50000 then perform demo_desktop.fail('invalid-input');end if;
 begin items:=case when left(p_region,9)='@regions:' then substring(p_region from 10)::jsonb else jsonb_build_array(jsonb_build_array(null,p_region)) end;exception when others then perform demo_desktop.fail('invalid-input');end;
 if jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items) not between 1 and 100 then perform demo_desktop.fail('invalid-input');end if;
 for item in select value from jsonb_array_elements(items) loop
  if jsonb_typeof(item) is distinct from 'array' or jsonb_array_length(item)<>2 or jsonb_typeof(item->0) not in ('null','string') or jsonb_typeof(item->1) is distinct from 'string' or length(item->>0)>100 or length(item->>1)>500 or (item->0='null'::jsonb and item->>1='') then perform demo_desktop.fail('invalid-input');end if;
 end loop;
 return (select jsonb_agg(v order by v) from (select distinct value v from jsonb_array_elements(items)) a);
end $$;
create or replace function demo_desktop.route_basis(p_owner uuid,p_workspace uuid,p_year integer default null,p_region text default '*') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;begin
 select coalesce(jsonb_agg(jsonb_build_array('annual:'||a.id,encode(sha256(convert_to(jsonb_build_array(a.customer_id,a.grave_id,g.data->>'address',g.data->>'business_region',
 case when l.data->>'address'=g.data->>'address' and l.data->'location'->>'source' in ('field','public_parcel') then l.data->'location' else null end,
 case when e.data->>'originalAddress'=g.data->>'address' then e.data else null end)::text,'UTF8')),'hex')) order by ('annual:'||a.id) collate "C"),'[]') into result
 from demo_desktop.annual_work a join demo_desktop.customers c on c.owner_id=a.owner_id and c.workspace_id=a.workspace_id and c.id=a.customer_id
 join demo_desktop.graves g on g.owner_id=a.owner_id and g.workspace_id=a.workspace_id and g.id=a.grave_id and g.customer_id=c.id
 left join demo_desktop.locations l on l.owner_id=g.owner_id and l.workspace_id=g.workspace_id and l.grave_id=g.id
 left join demo_desktop.earth_links e on e.owner_id=g.owner_id and e.workspace_id=g.workspace_id and e.grave_id=g.id
 where a.owner_id=p_owner and a.workspace_id=p_workspace and (p_year is null or a.year=p_year) and a.status='proceed' and a.deleted_at is null
 and nullif(c.data->>'deleted_at','') is null and coalesce(c.data->>'registration_status','registered')='registered' and nullif(g.data->>'deleted_at','') is null
 and (p_region='*' or demo_desktop.sales_region_matches(jsonb_build_object('region',demo_desktop.region(g.data->>'address'),'business_region',coalesce(g.data->>'business_region','')),p_region));
 return result;
end $$;
create or replace function demo_desktop.route_plans(p_owner uuid,p_workspace uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(data order by year,id),'[]') from demo_desktop.work_routes where owner_id=p_owner and workspace_id=p_workspace
$$;
create or replace function demo_desktop.save_work_route(p_owner uuid,p_workspace uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$
declare p jsonb:=p_input->'plan';y integer:=(p->>'year')::integer;scope jsonb;basis jsonb;old demo_desktop.work_routes;v bigint;route_id uuid;labels jsonb;created text;data jsonb;begin
 if p_input-array['type','plan','basis','expectedVersion']<>'{}' or p-array['year','regionFilter','startKey','workKeys']<>'{}' or jsonb_typeof(p) is distinct from 'object' or y is null or y not between 1 and 9999 or jsonb_typeof(p_input->'expectedVersion') is distinct from 'number' then perform demo_desktop.fail('invalid-input');end if;
 scope:=demo_desktop.route_selection(p->>'regionFilter');basis:=demo_desktop.route_basis(p_owner,p_workspace,y,p->>'regionFilter');
 if basis is distinct from p_input->'basis' then perform demo_desktop.fail('conflict');end if;
 if jsonb_typeof(p->'workKeys') is distinct from 'array' or jsonb_array_length(basis)=0 or jsonb_array_length(p->'workKeys')<>jsonb_array_length(basis) or p->'workKeys'->>0 is distinct from p->>'startKey' or exists(select from jsonb_array_elements(p->'workKeys') k where jsonb_typeof(k)<>'string') then perform demo_desktop.fail('invalid-input');end if;
 if (select jsonb_agg(a.item order by a.item) from (select distinct value item from jsonb_array_elements(p->'workKeys')) a) is distinct from (select jsonb_agg(value->0 order by value->0) from jsonb_array_elements(basis)) then perform demo_desktop.fail('invalid-input');end if;
 select * into old from demo_desktop.work_routes where owner_id=p_owner and workspace_id=p_workspace and year=y and identity=scope for update;
 if coalesce(old.version,0) is distinct from (p_input->>'expectedVersion')::bigint then perform demo_desktop.fail('conflict');end if;
 route_id:=coalesce(old.id,gen_random_uuid());v:=coalesce(old.version,0)+1;created:=coalesce(old.data->>'createdAt',clock_timestamp()::text);
 select jsonb_agg(case when value->>1<>'' then case when value->0='null'::jsonb then value->>1 else coalesce(nullif(value->>0,''),'미지정')||' · '||(value->>1) end else coalesce(nullif(value->>0,''),'미지정')||' 전체' end order by ordinal) into labels from jsonb_array_elements(case when left(p->>'regionFilter',9)='@regions:' then substring(p->>'regionFilter' from 10)::jsonb else scope end) with ordinality a(value,ordinal);
 data:=jsonb_build_object('id',route_id,'year',y,'regionFilter',p->>'regionFilter','regions',labels,'startKey',p->>'startKey','workKeys',p->'workKeys','basis',basis,'version',v,'createdAt',created,'updatedAt',clock_timestamp()::text);
 insert into demo_desktop.work_routes(owner_id,workspace_id,id,year,identity,version,data) values(p_owner,p_workspace,route_id,y,scope,v,data) on conflict(owner_id,workspace_id,year,identity) do update set version=excluded.version,data=excluded.data;
 return jsonb_build_object('routeId',route_id,'routeVersion',v);
end $$;
create or replace function demo_desktop.delete_work_route(p_owner uuid,p_workspace uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$
declare route_id uuid:=(p_input->>'id')::uuid;begin
 if p_input-array['type','id','expectedVersion']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 delete from demo_desktop.work_routes where owner_id=p_owner and workspace_id=p_workspace and id=route_id and version=(p_input->>'expectedVersion')::bigint;
 if not found then perform demo_desktop.fail('conflict');end if;return jsonb_build_object('routeId',route_id,'changed',true);
end $$;
-- Remove deleted subject IDs without ever retaining customer details in route plans.
create or replace function demo_desktop.prune_work_routes() returns trigger language plpgsql security definer set search_path='' as $$
declare o uuid:=coalesce(new.owner_id,old.owner_id);w uuid:=coalesce(new.workspace_id,old.workspace_id);p demo_desktop.work_routes;kept jsonb;begin
 for p in select * from demo_desktop.work_routes where owner_id=o and workspace_id=w loop
 select coalesce(jsonb_agg(k.value order by k.ordinal),'[]') into kept from jsonb_array_elements(p.data->'workKeys') with ordinality k(value,ordinal)
 where exists(select from demo_desktop.annual_work a join demo_desktop.customers c on c.owner_id=a.owner_id and c.workspace_id=a.workspace_id and c.id=a.customer_id join demo_desktop.graves g on g.owner_id=a.owner_id and g.workspace_id=a.workspace_id and g.id=a.grave_id and g.customer_id=c.id where a.owner_id=o and a.workspace_id=w and ('annual:'||a.id)=k.value#>>'{}' and a.deleted_at is null and nullif(c.data->>'deleted_at','') is null and nullif(g.data->>'deleted_at','') is null and coalesce(c.data->>'registration_status','registered')='registered');
 if kept is distinct from p.data->'workKeys' then
 update demo_desktop.work_routes set version=version+1,data=data||jsonb_build_object('workKeys',kept,'startKey',kept->>0,'basis',(select coalesce(jsonb_agg(b),'[]') from jsonb_array_elements(p.data->'basis') b where kept @> jsonb_build_array(b->0)),'invalidated',true,'version',p.version+1) where owner_id=o and workspace_id=w and id=p.id;
 end if;end loop;return null;
end $$;
do $$declare t text;begin foreach t in array array['annual_work','customers','graves'] loop
 execute format('drop trigger if exists prune_work_routes on demo_desktop.%I',t);
 execute format('create trigger prune_work_routes after update or delete on demo_desktop.%I for each row execute function demo_desktop.prune_work_routes()',t);
end loop;end $$;

create or replace function demo_desktop.region(p_address text) returns text language plpgsql immutable set search_path='' as $$
declare v text:=btrim(normalize(coalesce(p_address,''),NFC));m text[];begin
 if v~'^서울(특별시|시|\s)' then return '서울';end if;
 if v~'^(인천(광역시|시|\s)|강화군|옹진군)' then return '인천';end if;
 m:=regexp_match(v,'^(부산|대구|대전|울산|광주|세종)(광역시|특별자치시|시|\s)');if m is not null then return m[1];end if;
 v:=regexp_replace(v,'^(경기도?|강원(특별자치도|도)?|충청[남북]도|전라[남북]도|전북특별자치도|경상[남북]도|제주특별자치도)\s*','');
 m:=regexp_match(v,'^(가평|고양|과천|광명|광주|구리|군포|김포|남양주|동두천|부천|성남|수원|시흥|안산|안성|안양|양주|양평|여주|연천|오산|용인|의왕|의정부|이천|파주|평택|포천|하남|화성)(시|군|\s|$)');if m is not null then return m[1];end if;
 m:=regexp_match(v,'^([가-힣]{2,})(시|군)(\s|$)');return coalesce(m[1],'미분류');
end $$;
-- The link uses grave_id, while grave primary keys use id.
create or replace function demo_desktop.grave_view(p_owner uuid,p_workspace uuid,p_grave bigint) returns jsonb
language sql stable security definer set search_path='' as $$
 select g.data||jsonb_build_object('id',g.id,'customer_id',g.customer_id,'address',coalesce(g.data->>'address',''),'region',demo_desktop.region(g.data->>'address'),'business_region',coalesce(g.data->>'business_region',''),
 'payments',(select coalesce(jsonb_agg(p.data||jsonb_build_object('id',p.id,'grave_id',p.grave_id,'year',p.year,'kind',p.kind,'amount',p.amount) order by p.year,p.id),'[]') from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=g.id))
 ||case when e.grave_id is null then '{}'::jsonb else jsonb_build_object('earth',e.data) end
 from demo_desktop.graves g left join demo_desktop.earth_links e on e.owner_id=g.owner_id and e.workspace_id=g.workspace_id and e.grave_id=g.id
 where g.owner_id=p_owner and g.workspace_id=p_workspace and g.id=p_grave;
$$;
create or replace function demo_desktop.sales_contact(p_owner uuid,p_workspace uuid,p_customer bigint,p_year integer) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('customerId',c.id,'graveId',g.id,'key',case when a.id is null then '' else 'annual:'||a.id end,
 'name',coalesce(c.data->>'name',''),'phone',coalesce(nullif(c.data->>'phone_raw',''),c.data->>'phone',''),
 'address',coalesce(g.data->>'address',''),'region',demo_desktop.region(g.data->>'address'),'business_region',coalesce(g.data->>'business_region',''),
 'gisu',coalesce(g.data->>'gisu',''),'pyeong',coalesce(g.data->>'pyeong',''),'number',coalesce(g.data->>'gubun',''),
 'status',case when a.deleted_at is not null then 'uncontacted' else coalesce(a.status,'uncontacted') end,'requirements',coalesce(c.data->>'memo',''),'notes',coalesce(c.data->>'special_notes',''),
 'deadline',coalesce(a.data->>'deadline',''),'deleted_at',coalesce(c.data->>'deleted_at',g.data->>'deleted_at'),
 'workDeletedAt',a.deleted_at,'previousAmount',coalesce((select p.amount::text from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=g.id and p.kind='annual' and p.year=p_year-1),''),
 'currentAmount',coalesce((select p.amount::text from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=g.id and p.kind='annual' and p.year=p_year),''),
 'revision','customer:'||c.id||':'||c.version)
 from demo_desktop.customers c left join demo_desktop.annual_work a on a.owner_id=c.owner_id and a.workspace_id=c.workspace_id and a.customer_id=c.id and a.year=p_year
 left join lateral(select g.* from demo_desktop.graves g where g.owner_id=c.owner_id and g.workspace_id=c.workspace_id and g.customer_id=c.id
 and ((a.grave_id is not null and g.id=a.grave_id) or (a.grave_id is null and coalesce(g.data->>'is_active','1')='1')) order by g.id limit 1) g on true
 where c.owner_id=p_owner and c.workspace_id=p_workspace and c.id=p_customer;
$$;

create or replace function demo_desktop.snapshot(p_owner uuid,p_workspace uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare customers jsonb;graves jsonb;payments jsonb;annual jsonb;works jsonb;locations jsonb;earth jsonb;versions jsonb;catalog jsonb;rev text;begin
 select 'desktop:'||revision into rev from demo_desktop.companies where owner_id=p_owner and workspace_id=p_workspace and active;
 if rev is null then perform demo_desktop.fail('not-shared');end if;
 select coalesce(jsonb_agg(data||jsonb_build_object('id',id) order by id),'[]') into customers from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace;
 select coalesce(jsonb_agg(data||jsonb_build_object('id',id,'customer_id',customer_id) order by id),'[]') into graves from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace;
 select coalesce(jsonb_agg(data||jsonb_build_object('id',id,'grave_id',grave_id,'year',year,'kind',kind,'amount',amount) order by id),'[]') into payments from demo_desktop.payments where owner_id=p_owner and workspace_id=p_workspace;
 select coalesce(jsonb_agg(data||jsonb_build_object('id',id,'year',year,'customer_id',customer_id,'grave_id',grave_id,'status',status,'version',version,'deleted_at',deleted_at) order by year,customer_id),'[]') into annual from demo_desktop.annual_work where owner_id=p_owner and workspace_id=p_workspace;
 select coalesce(jsonb_agg(data order by key),'[]') into works from demo_desktop.work_rows where owner_id=p_owner and workspace_id=p_workspace;
 select coalesce(jsonb_agg(data order by grave_id),'[]') into locations from demo_desktop.locations where owner_id=p_owner and workspace_id=p_workspace;
 select coalesce(jsonb_agg(jsonb_build_object('graveId',grave_id,'versionId',version_id,'summary',data) order by grave_id),'[]') into earth from demo_desktop.earth_links where owner_id=p_owner and workspace_id=p_workspace;
 select coalesce(jsonb_object_agg(key,version),'{}') into versions from (
 select 'customer:'||id key,version::text version from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace
 union all select 'grave:'||id,version::text from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and customer_id is null) v;
 catalog:=jsonb_build_object('format','demo-catalog','version',1,'workspaceId',p_workspace,'revision',rev,
 'customers',(select coalesce(jsonb_agg(c.data||jsonb_build_object('id',c.id,'name',coalesce(nullif(c.data->>'name',''),'이름 미등록'),'phone',coalesce(nullif(c.data->>'phone',''),c.data->>'phone_raw',''),
 'graves',(select coalesce(jsonb_agg(demo_desktop.grave_view(p_owner,p_workspace,g.id) order by g.id),'[]') from demo_desktop.graves g where g.owner_id=p_owner and g.workspace_id=p_workspace and g.customer_id=c.id),
 'regions',coalesce((select jsonb_agg(region order by region) from (select distinct demo_desktop.region(g.data->>'address') region from demo_desktop.graves g where g.owner_id=p_owner and g.workspace_id=p_workspace and g.customer_id=c.id) r),'["미분류"]'::jsonb)) order by c.id),'[]') from demo_desktop.customers c where c.owner_id=p_owner and c.workspace_id=p_workspace),
 'unassignedGraves',(select coalesce(jsonb_agg(demo_desktop.grave_view(p_owner,p_workspace,g.id) order by g.id),'[]') from demo_desktop.graves g where g.owner_id=p_owner and g.workspace_id=p_workspace and g.customer_id is null),
 'workRows',works||(select coalesce(jsonb_agg(jsonb_build_object('key',r->>'key','customerId',r->'customerId','graveId',r->'graveId','serviceYear',a.year,'sequence',r->>'region','number',r->>'number','address',r->>'address','name',r->>'name','gisu',r->>'gisu','notes',r->>'notes','deadline',r->>'deadline','rowNumber',1,'workbookName','','sheetName','')||case when r->>'deleted_at' is null then '{}'::jsonb else jsonb_build_object('deleted_at',r->>'deleted_at') end order by a.customer_id),'[]')
 from demo_desktop.annual_work a cross join lateral(select demo_desktop.sales_contact(p_owner,p_workspace,a.customer_id,a.year) r) x
 where a.owner_id=p_owner and a.workspace_id=p_workspace and a.status='proceed' and a.deleted_at is null and a.year=extract(year from clock_timestamp() at time zone 'Asia/Seoul')::int));
 return jsonb_build_object('protocol',1,'ownerId',p_owner,'workspaceId',p_workspace,'mode','shared','revision',rev,'customers',customers,'graves',graves,'payments',payments,'annualWork',annual,'workRoutes',demo_desktop.route_plans(p_owner,p_workspace),'workRouteBasis',demo_desktop.route_basis(p_owner,p_workspace),'workRows',works,'locations',locations,'earthLinks',earth,'versions',versions,'catalog',catalog,'mapSnapshot',jsonb_build_object('workspaceId',p_workspace,'locations',(select coalesce(jsonb_agg(jsonb_build_object('id',l.grave_id,'address',l.data->'address','region',demo_desktop.region(coalesce(l.data->>'lookupAddress',l.data->>'address')),'location',jsonb_build_object('lat',l.data->'location'->'lat','lng',l.data->'location'->'lng','source',l.data->'location'->'source')) order by l.grave_id),'[]') from demo_desktop.locations l join demo_desktop.graves g on g.owner_id=l.owner_id and g.workspace_id=l.workspace_id and g.id=l.grave_id where l.owner_id=p_owner and l.workspace_id=p_workspace and l.data->>'address'=coalesce(g.data->>'address','') and nullif(g.data->>'deleted_at','') is null and l.data->'location'->>'source' in ('field','public_parcel') and not exists(select from demo_desktop.customers c where c.owner_id=p_owner and c.workspace_id=p_workspace and c.id=g.customer_id and (nullif(c.data->>'deleted_at','') is not null or c.data->>'registration_status'='declined')))));
end $$;
create or replace function demo_desktop.refresh_projection(p_owner uuid,p_workspace uuid) returns void
language plpgsql security definer set search_path='' as $$declare s jsonb;begin
 update demo_desktop.companies set revision=revision+1 where owner_id=p_owner and workspace_id=p_workspace and active;
 s:=demo_desktop.snapshot(p_owner,p_workspace);
 update public.demo_catalogs set payload=s->'catalog',revision=s->>'revision',desktop_shared=true where owner_id=p_owner and workspace_id=p_workspace;
 insert into public.demo_map_snapshots(owner_id,workspace_id,payload) values(p_owner,p_workspace,s->'mapSnapshot')
 on conflict(owner_id,workspace_id) do update set payload=excluded.payload;
end $$;
