create or replace function demo_desktop.registration_values(p_values jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$declare result jsonb:='{}';k text;v text;n numeric;begin
 if jsonb_typeof(p_values) is distinct from 'object' or p_values-array['name','phone','address','gisu','pyeong','isManaged','businessRegion','amount','requirements','specialNotes','amount2023','amount2024','amount2025','amount2026']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 foreach k in array array['name','phone','address','gisu','requirements','specialNotes','businessRegion'] loop
  v:=demo_desktop.text_value(p_values,k,case when k='businessRegion' then 100 when k in ('name','phone','address') then 4000 else 10000 end);
  result:=result||jsonb_build_object(k,v);
 end loop;
 foreach k in array array['pyeong','amount','amount2023','amount2024','amount2025','amount2026'] loop
  n:=demo_desktop.number_value(p_values,k,k='pyeong');result:=result||jsonb_build_object(k,n);
 end loop;
 if result->>'businessRegion' ~ '[[:cntrl:]]' then perform demo_desktop.fail('invalid-input');end if;
 if p_values ? 'isManaged' then
  if jsonb_typeof(p_values->'isManaged') is distinct from 'string' or p_values->>'isManaged' not in ('0','1') then perform demo_desktop.fail('invalid-input');end if;
  result:=result||jsonb_build_object('isManaged',(p_values->>'isManaged')::integer);
 end if;
 return result;
end $$;
create or replace function demo_desktop.write_payment(p_owner uuid,p_workspace uuid,p_grave bigint,p_year integer,p_kind text,p_amount bigint,p_source text) returns bigint
language plpgsql set search_path='' as $$declare payment_id bigint;begin
 select p.id into payment_id from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=p_grave and p.year=p_year and p.kind=p_kind;
 if payment_id is null then
  payment_id:=demo_desktop.next_id(p_owner,p_workspace,'payments');
  insert into demo_desktop.payments(owner_id,workspace_id,id,grave_id,year,kind,amount,data) values(p_owner,p_workspace,payment_id,p_grave,p_year,p_kind,p_amount,jsonb_build_object('source',p_source));
 else update demo_desktop.payments set amount=p_amount,data=data||jsonb_build_object('source',p_source) where owner_id=p_owner and workspace_id=p_workspace and payments.id=payment_id;end if;
 return payment_id;
end $$;
create or replace function demo_desktop.register(p_owner uuid,p_workspace uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$declare v jsonb;cid bigint;gid bigint;y integer;amount bigint;year_now integer:=extract(year from clock_timestamp() at time zone 'Asia/Seoul');candidate record;status text:=coalesce(p_input->>'registrationStatus','registered');phone text;begin
 if p_input-array['type','values','registrationStatus','preparationId']<>'{}' or status not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
 v:=demo_desktop.registration_values(p_input->'values');
 if not exists(select from jsonb_each(v) where value<>'null'::jsonb and (key<>'isManaged' or value='1'::jsonb)) then perform demo_desktop.fail('invalid-input');end if;
 if p_input ? 'preparationId' then
 select * into candidate from demo_desktop.earth_candidates where owner_id=p_owner and workspace_id=p_workspace and id=(p_input->>'preparationId')::uuid and actor_id=auth.uid() and state='prepared' and target->'newCustomer'='true'::jsonb;
 if not found then perform demo_desktop.fail('conflict');end if;cid:=candidate.customer_id;gid:=candidate.grave_id;
 else cid:=demo_desktop.next_id(p_owner,p_workspace,'customers');gid:=demo_desktop.next_id(p_owner,p_workspace,'graves');end if;phone:=nullif(regexp_replace(v->>'phone','[^0-9]','','g'),'');
 insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(p_owner,p_workspace,cid,jsonb_build_object('name',v->'name','phone',phone,'phone_raw',v->'phone','phone_ok',case when v->>'phone' is null or phone~'^0[0-9]{8,10}$' then 1 else 0 end,'memo',v->'requirements','special_notes',v->'specialNotes','registration_status',status,'deleted_at',null,'created_at',clock_timestamp()::text));
 insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(p_owner,p_workspace,gid,cid,jsonb_build_object('address',v->'address','gisu',v->'gisu','pyeong',v->'pyeong','is_managed',coalesce(v->'isManaged','0'::jsonb),'business_region',v->'businessRegion','is_active',1,'deleted_at',null,'created_at',clock_timestamp()::text));
 for y in 2023..2026 loop
  amount:=(v->>('amount'||y))::bigint;
  if y=year_now and v->>'amount' is not null then
   if amount is not null and amount<>(v->>'amount')::bigint then perform demo_desktop.fail('invalid-input');end if;amount:=(v->>'amount')::bigint;
  end if;
  if amount is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,y,'annual',amount,'desktop');end if;
 end loop;
 if year_now not between 2023 and 2026 and v->>'amount' is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,year_now,'annual',(v->>'amount')::bigint,'desktop');end if;
 if status='registered' then insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,data) values(p_owner,p_workspace,gen_random_uuid(),year_now,cid,gid,'proceed',jsonb_build_object('notes',coalesce(v->>'specialNotes',''),'deadline',''));end if;
 if p_input ? 'preparationId' then perform demo_desktop.connect_earth(p_owner,p_workspace,null,p_input,true);end if;
 return jsonb_build_object('customerId',cid,'graveId',gid);
end $$;
create or replace function demo_desktop.edit_values(p_values jsonb,p_customer jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$declare adjusted jsonb:=p_values;v jsonb;k text;column_name text;begin
 if jsonb_typeof(p_values) is distinct from 'object' or p_values-array['name','phone','address','gisu','pyeong','isManaged','businessRegion','requirements','specialNotes']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 foreach k in array array['requirements','specialNotes'] loop
  column_name:=case k when 'requirements' then 'memo' else 'special_notes' end;
  if not p_values ? k or p_values->>k is not distinct from coalesce(p_customer->>column_name,'') then adjusted:=adjusted||jsonb_build_object(k,'');end if;
 end loop;
 v:=demo_desktop.registration_values(adjusted);
 foreach k in array array['requirements','specialNotes'] loop
  column_name:=case k when 'requirements' then 'memo' else 'special_notes' end;
  if not p_values ? k or p_values->>k is not distinct from coalesce(p_customer->>column_name,'') then v:=v||jsonb_build_object(k,p_customer->column_name);end if;
 end loop;
 return v;
end $$;

create or replace function demo_desktop.update_customers(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare i jsonb;v jsonb;customer jsonb;grave jsonb;cid bigint;gid bigint;k text;phone text;payment jsonb;pid bigint;amount bigint;shared jsonb:='{}';targets text[]:='{}';entity text;canonical jsonb;rows jsonb:='[]';begin
 if p_input-array['type','inputs']<>'{}' or jsonb_typeof(p_input->'inputs') is distinct from 'array' or jsonb_array_length(p_input->'inputs') not between 1 and 20000 then perform demo_desktop.fail('invalid-input');end if;
 for i in select value from jsonb_array_elements(p_input->'inputs') loop
  if jsonb_typeof(i) is distinct from 'object' or i-array['customerId','graveId','revision','values','payments']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  cid:=(i->>'customerId')::bigint;gid:=(i->>'graveId')::bigint;
  if demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from i->>'revision' then perform demo_desktop.fail('conflict');end if;
  entity:=coalesce(cid::text,'')||':'||coalesce(gid::text,'');if entity=any(targets) then perform demo_desktop.fail('invalid-input');end if;targets:=array_append(targets,entity);
  if cid is not null then
   perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
   select data into customer from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
   v:=demo_desktop.edit_values(i->'values',customer);
   if nullif(customer->>'deleted_at','') is not null then perform demo_desktop.fail('conflict');end if;
   canonical:=jsonb_build_object('name',case when i->'values' ? 'name' then demo_desktop.text_value(i->'values','name',4000) else customer->>'name' end,
    'phone',case when i->'values' ? 'phone' then demo_desktop.text_value(i->'values','phone',4000) else coalesce(customer->>'phone_raw',customer->>'phone') end,
    'requirements',v->'requirements',
    'specialNotes',v->'specialNotes');
   if shared ? cid::text and shared->cid::text<>canonical then perform demo_desktop.fail('conflict');end if;shared:=shared||jsonb_build_object(cid::text,canonical);
  end if;
  if gid is not null and exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
  v:=demo_desktop.edit_values(i->'values',coalesce(customer,'{}'::jsonb));
  if jsonb_typeof(i->'payments') is distinct from 'array' then perform demo_desktop.fail('invalid-input');end if;
 end loop;
 for i in select value from jsonb_array_elements(p_input->'inputs') loop
  cid:=(i->>'customerId')::bigint;gid:=(i->>'graveId')::bigint;
  select data into customer from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
  v:=demo_desktop.edit_values(i->'values',coalesce(customer,'{}'::jsonb));
  if cid is null and exists(select from jsonb_each(v) where key in ('name','phone','requirements','specialNotes') and value<>'null'::jsonb) then
   cid:=demo_desktop.next_id(p_owner,p_workspace,'customers');insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(p_owner,p_workspace,cid,'{}');
   update demo_desktop.graves set customer_id=cid where owner_id=p_owner and workspace_id=p_workspace and id=gid;
  end if;
  if cid is not null then
   select data into customer from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
   foreach k in array array['name','requirements','specialNotes'] loop
    if i->'values' ? k then customer:=customer||jsonb_build_object(case k when 'requirements' then 'memo' when 'specialNotes' then 'special_notes' else k end,v->k);end if;
   end loop;
   if i->'values' ? 'phone' then phone:=nullif(regexp_replace(v->>'phone','[^0-9]','','g'),'');customer:=customer||jsonb_build_object('phone_raw',v->'phone','phone',phone,'phone_ok',case when v->>'phone' is null or phone~'^0[0-9]{8,10}$' then 1 else 0 end);end if;
   update demo_desktop.customers set data=customer where owner_id=p_owner and workspace_id=p_workspace and id=cid;
  end if;
  if gid is null and (v->>'address' is not null or v->>'gisu' is not null or v->>'pyeong' is not null or v->>'isManaged'='1' or v->>'businessRegion' is not null or exists(select from jsonb_array_elements(i->'payments') p where nullif(p->>'amount','') is not null)) then
   gid:=demo_desktop.next_id(p_owner,p_workspace,'graves');insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(p_owner,p_workspace,gid,cid,jsonb_build_object('is_active',1));
  end if;
  if gid is not null then
   select data into grave from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid;
   foreach k in array array['address','gisu','pyeong','isManaged','businessRegion'] loop if i->'values' ? k then grave:=grave||jsonb_build_object(case k when 'isManaged' then 'is_managed' when 'businessRegion' then 'business_region' else k end,v->k);end if;end loop;
   update demo_desktop.graves set data=grave where owner_id=p_owner and workspace_id=p_workspace and id=gid;
   for payment in select value from jsonb_array_elements(i->'payments') loop
    if jsonb_typeof(payment) is distinct from 'object' or payment-array['id','grave_id','year','kind','amount','paid_at','method','source','note']<>'{}' or jsonb_typeof(payment->'year') is distinct from 'number' or (payment->>'year')::numeric not between 1 and 9999 or (payment->>'year')::numeric<>trunc((payment->>'year')::numeric) or jsonb_typeof(payment->'kind') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
    amount:=demo_desktop.number_value(payment,'amount');pid:=(payment->>'id')::bigint;
    if pid is not null then
     if amount is null or not exists(select from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.id=pid and p.grave_id=gid and p.year=(payment->>'year')::int and p.kind=payment->>'kind') then perform demo_desktop.fail('conflict');end if;
     update demo_desktop.payments set amount=update_customers.amount where owner_id=p_owner and workspace_id=p_workspace and id=pid;
    elsif amount is not null then
     if exists(select from demo_desktop.payments p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=gid and p.year=(payment->>'year')::int and p.kind=payment->>'kind') then perform demo_desktop.fail('conflict');end if;
     perform demo_desktop.write_payment(p_owner,p_workspace,gid,(payment->>'year')::int,payment->>'kind',amount,'desktop');
    end if;
   end loop;
  end if;
  perform demo_desktop.bump(p_owner,p_workspace,cid,gid);rows:=rows||jsonb_build_array(jsonb_build_object('customerId',cid,'graveId',gid));
 end loop;
 return jsonb_build_object('rows',rows);
end $$;
create or replace function demo_desktop.archive(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$declare cid bigint:=(p_input->>'customerId')::bigint;gid bigint:=(p_input->>'graveId')::bigint;at text;begin
 if p_input-array['type','customerId','graveId','revision','archived']<>'{}' or jsonb_typeof(p_input->'archived') is distinct from 'boolean' then perform demo_desktop.fail('invalid-input');end if;
 if demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from p_input->>'revision' then perform demo_desktop.fail('conflict');end if;
 if cid is not null then perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);end if;
 at:=case when (p_input->>'archived')::boolean then clock_timestamp()::text else null end;
 if cid is not null then update demo_desktop.customers set data=data||jsonb_build_object('deleted_at',at) where owner_id=p_owner and workspace_id=p_workspace and id=cid;
 else update demo_desktop.graves set data=data||jsonb_build_object('deleted_at',at) where owner_id=p_owner and workspace_id=p_workspace and id=gid;end if;
 perform demo_desktop.bump(p_owner,p_workspace,cid,gid);
 return jsonb_build_object('customerId',cid,'graveId',gid,'deletedAt',at);
end $$;
create or replace function demo_desktop.permanent_delete(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$declare cid bigint:=(p_input->>'customerId')::bigint;gid bigint:=(p_input->>'graveId')::bigint;ids bigint[];counter_name text;maximum bigint;begin
 if p_input-array['type','customerId','graveId','revision']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 if demo_desktop.entity_revision(p_owner,p_workspace,cid,gid) is distinct from p_input->>'revision' then perform demo_desktop.fail('conflict');end if;
 if cid is not null then
  perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
  if not exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
  select array_agg(id) into ids from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid;
 else
  if not exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=gid and nullif(data->>'deleted_at','') is not null) then perform demo_desktop.fail('conflict');end if;
  ids:=array[gid];
 end if;
 foreach counter_name in array array['customers','graves','payments'] loop
  execute format('select coalesce(max(id),0) from demo_desktop.%I where owner_id=$1 and workspace_id=$2',counter_name) into maximum using p_owner,p_workspace;
  insert into demo_desktop.id_counters(owner_id,workspace_id,name,high_water) values(p_owner,p_workspace,counter_name,maximum) on conflict(owner_id,workspace_id,name) do update set high_water=greatest(demo_desktop.id_counters.high_water,excluded.high_water);
 end loop;
 delete from demo_desktop.locations where owner_id=p_owner and workspace_id=p_workspace and grave_id=any(ids);
 delete from demo_desktop.earth_links where owner_id=p_owner and workspace_id=p_workspace and grave_id=any(ids);
 delete from demo_desktop.payments where owner_id=p_owner and workspace_id=p_workspace and grave_id=any(ids);
 delete from demo_desktop.annual_work where owner_id=p_owner and workspace_id=p_workspace and (customer_id=cid or grave_id=any(ids));
 delete from demo_desktop.work_rows where owner_id=p_owner and workspace_id=p_workspace and ((data->>'customerId')::bigint=cid or (data->>'graveId')::bigint=any(ids));
 delete from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=any(ids);
 if cid is not null then delete from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;end if;
 return jsonb_build_object('customerId',cid,'graveId',gid);
end $$;

create or replace function demo_desktop.delete_work(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$declare r jsonb;cid bigint:=(p_input->>'customerId')::bigint;y integer:=(p_input->>'year')::integer;begin
 if p_input-array['type','year','customerId','key','revision']<>'{}' or jsonb_typeof(p_input->'year') is distinct from 'number' or (p_input->>'year')::numeric<>y or y not between 1 and 9999 then perform demo_desktop.fail('invalid-input');end if;
 r:=demo_desktop.sales_contact(p_owner,p_workspace,cid,y);
 if r is null or r->>'revision' is distinct from p_input->>'revision' or r->>'key' is distinct from p_input->>'key' or coalesce(r->>'key','')='' or r->>'deleted_at' is not null or r->>'workDeletedAt' is not null then perform demo_desktop.fail('conflict');end if;
 perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
 update demo_desktop.annual_work set deleted_at=clock_timestamp()::text,version=version+1 where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid and year=y;
 perform demo_desktop.bump(p_owner,p_workspace,cid,(r->>'graveId')::bigint);return jsonb_build_object('customerId',cid,'year',y,'key',r->>'key');
end $$;
create or replace function public.demo_desktop_command(p_workspace uuid,p_session uuid,p_request uuid,p_input jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;a uuid:=auth.uid();fingerprint text;previous demo_desktop.requests;result jsonb;begin
 o:=demo_desktop.assert_actor(p_workspace);
 if p_session is null or p_request is null or jsonb_typeof(p_input) is distinct from 'object' or octet_length(p_input::text)>20000000 then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);
 perform demo_desktop.lock_actor(p_workspace,o);
 fingerprint:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
 select * into previous from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=a and request_id=p_request;
 if found then
  if previous.input_sha<>fingerprint then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'result',previous.result,'snapshot',demo_desktop.snapshot(o,p_workspace));
 end if;
 case p_input->>'type'
 when 'location-save' then if p_input ? 'approve' then result:=demo_desktop.review_location(o,p_workspace,p_session,p_input);else result:=demo_desktop.save_location(o,p_workspace,p_session,p_input);end if;
 when 'earth-prepare' then result:=demo_desktop.prepare_earth(o,p_workspace,p_session,p_input);
 when 'earth-connect' then result:=demo_desktop.connect_earth(o,p_workspace,p_session,p_input);
 when 'register' then result:=demo_desktop.register(o,p_workspace,p_input);
 when 'update-customers' then result:=demo_desktop.update_customers(o,p_workspace,p_session,p_input);
 when 'archive' then result:=demo_desktop.archive(o,p_workspace,p_session,p_input);
 when 'permanent-delete' then result:=demo_desktop.permanent_delete(o,p_workspace,p_session,p_input);
 when 'work-delete' then result:=demo_desktop.delete_work(o,p_workspace,p_session,p_input);
 when 'work-route-save' then result:=demo_desktop.save_work_route(o,p_workspace,p_input);
 when 'work-route-delete' then result:=demo_desktop.delete_work_route(o,p_workspace,p_input);
 when 'sales-save' then result:=demo_desktop.save_sales(o,p_workspace,p_session,p_input);
 else perform demo_desktop.fail('invalid-input');end case;
 if to_regprocedure('demo_desktop.refresh_sent_amounts(uuid,uuid)') is not null then perform demo_desktop.refresh_sent_amounts(o,p_workspace);end if;
 perform demo_desktop.refresh_projection(o,p_workspace);
 insert into demo_desktop.requests(owner_id,workspace_id,actor_id,request_id,session_id,input_sha,result) values(o,p_workspace,a,p_request,p_session,fingerprint,result);
 return jsonb_build_object('requestId',p_request,'result',result,'snapshot',demo_desktop.snapshot(o,p_workspace));
end $$;
create or replace function public.demo_desktop_result(p_workspace uuid,p_request uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare o uuid;r jsonb;begin
 o:=demo_desktop.assert_actor(p_workspace);
 select result into r from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=auth.uid() and request_id=p_request;
 if not found then return jsonb_build_object('state','not-found','requestId',p_request);end if;
 return jsonb_build_object('state','committed','requestId',p_request,'result',r);
end $$;
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;
revoke all on function public.demo_desktop_command(uuid,uuid,uuid,jsonb),public.demo_desktop_result(uuid,uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_command(uuid,uuid,uuid,jsonb),public.demo_desktop_result(uuid,uuid) to authenticated;

create table if not exists demo_desktop.sales_assignments (
 owner_id uuid not null,workspace_id uuid not null,customer_id bigint not null,
 actor_id uuid not null,auth_session_id uuid not null,session_id uuid not null,token uuid not null,
 service_year integer not null,state text not null check(state in ('active','needs_review','released')),
 last_seen_at timestamptz not null default clock_timestamp(),created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,workspace_id,customer_id),foreign key(owner_id,workspace_id,customer_id) references demo_desktop.customers(owner_id,workspace_id,id) on delete cascade
);
alter table demo_desktop.sales_assignments add column if not exists resume_from_token uuid;
create unique index if not exists sales_one_customer_per_session on demo_desktop.sales_assignments(owner_id,workspace_id,actor_id,session_id) where state<>'released';
create table if not exists demo_desktop.sales_audit (
 id uuid primary key default gen_random_uuid(),owner_id uuid not null,workspace_id uuid not null,
 customer_id bigint not null,actor_id uuid not null,session_id uuid not null,action text not null,lease_token uuid,reason text not null default '',at timestamptz not null default clock_timestamp()
);
alter table demo_desktop.sales_assignments enable row level security;
alter table demo_desktop.sales_audit enable row level security;
revoke all on demo_desktop.sales_assignments,demo_desktop.sales_audit from public,anon,authenticated,service_role,demo_desktop_writer;
create or replace function demo_desktop.expire_assignments(p_owner uuid,p_workspace uuid) returns void language plpgsql set search_path='' as $$begin
 update demo_desktop.sales_assignments a set state='needs_review' where a.owner_id=p_owner and a.workspace_id=p_workspace and a.state='active'
 and (a.last_seen_at<=clock_timestamp()-interval '90 seconds' or not exists(select from auth.sessions s where s.id=a.auth_session_id and s.user_id=a.actor_id));
end $$;
create or replace function demo_desktop.lease_json(p_lease demo_desktop.sales_assignments) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('customerId',p_lease.customer_id,'sessionId',p_lease.session_id,'token',p_lease.token,'state',p_lease.state,'lastSeenAt',p_lease.last_seen_at);
$$;
create or replace function demo_desktop.assert_editable(p_owner uuid,p_workspace uuid,p_session uuid,p_customer bigint,p_token uuid default null) returns void language plpgsql set search_path='' as $$declare a demo_desktop.sales_assignments;begin
 if not exists(select from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=p_customer) then perform demo_desktop.fail('conflict');end if;
 select * into a from demo_desktop.sales_assignments where owner_id=p_owner and workspace_id=p_workspace and customer_id=p_customer;
 if found and a.state<>'released' and (a.state<>'active' or a.actor_id<>auth.uid() or a.auth_session_id<>demo_desktop.auth_session() or a.session_id<>p_session or a.last_seen_at<=clock_timestamp()-interval '90 seconds' or (p_token is not null and a.token<>p_token)) then perform demo_desktop.fail('lease-unavailable');end if;
end $$;



create or replace function demo_desktop.sales_name_matches(p_row jsonb,p_query text) returns boolean language sql immutable set search_path='' as $$
 select strpos(lower(regexp_replace(coalesce(p_row->>'name',''),'[[:space:]]','','g')),lower(regexp_replace(coalesce(p_query,''),'[[:space:]]','','g')))>0;
$$;
create or replace function demo_desktop.sales_region_matches(p_row jsonb,p_region text) returns boolean language plpgsql immutable set search_path='' as $$declare filters jsonb;f jsonb;matched boolean:=false;begin
 if p_region='*' then return true;end if;
 if left(p_region,9)<>'@regions:' then if length(p_region)>500 then perform demo_desktop.fail('invalid-input');end if;return p_row->>'region'=p_region;end if;
 begin filters:=substring(p_region from 10)::jsonb;exception when others then perform demo_desktop.fail('invalid-input');end;
 if jsonb_typeof(filters) is distinct from 'array' or jsonb_array_length(filters) not between 1 and 100 then perform demo_desktop.fail('invalid-input');end if;
 for f in select value from jsonb_array_elements(filters) loop
  if jsonb_typeof(f) is distinct from 'array' or jsonb_array_length(f)<>2 then perform demo_desktop.fail('invalid-input');end if;
  if jsonb_typeof(f->0) not in ('null','string') or jsonb_typeof(f->1) is distinct from 'string' or length(f->>0)>100 or length(f->>1)>500 then perform demo_desktop.fail('invalid-input');end if;
  if (f->0='null'::jsonb or coalesce(btrim(p_row->>'business_region'),'')=f->>0) and (f->>1='' or p_row->>'region'=f->>1) then matched:=true;end if;
 end loop;
 return matched;
end $$;
create or replace function demo_desktop.sales_region_groups(p_owner uuid,p_workspace uuid,p_year integer) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('region',region,'business_region',business_region,'availableCount',n) order by business_region,region),'[]') from (
 select coalesce(demo_desktop.sales_contact(p_owner,p_workspace,c.id,p_year)->>'region','미분류') region,coalesce(demo_desktop.sales_contact(p_owner,p_workspace,c.id,p_year)->>'business_region','') business_region,count(*) n
 from demo_desktop.customers c where c.owner_id=p_owner and c.workspace_id=p_workspace and coalesce(c.data->>'registration_status','registered')='registered' and nullif(c.data->>'deleted_at','') is null and demo_desktop.sales_contact(p_owner,p_workspace,c.id,p_year)->>'deleted_at' is null
 and not exists(select from demo_desktop.annual_work w where w.owner_id=p_owner and w.workspace_id=p_workspace and w.customer_id=c.id and w.year=p_year and w.deleted_at is null)
 and not exists(select from demo_desktop.sales_assignments l where l.owner_id=p_owner and l.workspace_id=p_workspace and l.customer_id=c.id and l.state<>'released') group by 1,2) grouped;
$$;
create or replace function demo_desktop.available_sales_count(p_owner uuid,p_workspace uuid,p_year integer,p_region text) returns bigint language sql stable set search_path='' as $$
 select count(*) from demo_desktop.customers c where c.owner_id=p_owner and c.workspace_id=p_workspace and coalesce(c.data->>'registration_status','registered')='registered' and nullif(c.data->>'deleted_at','') is null and demo_desktop.sales_contact(p_owner,p_workspace,c.id,p_year)->>'deleted_at' is null
 and demo_desktop.sales_region_matches(demo_desktop.sales_contact(p_owner,p_workspace,c.id,p_year),p_region)
 and not exists(select from demo_desktop.annual_work w where w.owner_id=p_owner and w.workspace_id=p_workspace and w.customer_id=c.id and w.year=p_year and w.deleted_at is null)
 and not exists(select from demo_desktop.sales_assignments l where l.owner_id=p_owner and l.workspace_id=p_workspace and l.customer_id=c.id and l.state<>'released');
$$;

create or replace function public.demo_sales_assignment(p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);actor uuid:=auth.uid();login_session uuid:=demo_desktop.auth_session();a demo_desktop.sales_assignments;cid bigint;year_value integer;region_value text;after_id bigint;direction_value text;action text:=p_input->>'action';token_value uuid;count_value bigint;reason_value text;begin
 if p_session is null or jsonb_typeof(p_input) is distinct from 'object' or p_input-array['action','year','region','customerId','token','confirmedEnded','afterCustomerId','direction','reason','nameQuery']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);perform demo_desktop.lock_actor(p_workspace,o);perform demo_desktop.expire_assignments(o,p_workspace);
 if action in ('regions','claim') then
  if jsonb_typeof(p_input->'year') is distinct from 'number' or (p_input->>'year')::numeric not between 1 and 9999 or (p_input->>'year')::numeric<>trunc((p_input->>'year')::numeric) then perform demo_desktop.fail('invalid-input');end if;year_value:=(p_input->>'year')::int;
 end if;
 if action='regions' then
  return jsonb_build_object('year',year_value,'regionGroups',demo_desktop.sales_region_groups(o,p_workspace,year_value),'regions',(select coalesce(jsonb_agg(jsonb_build_object('region',region,'availableCount',n) order by region),'[]') from (
   select demo_desktop.region((demo_desktop.sales_contact(o,p_workspace,c.id,year_value))->>'address') region,count(*) n from demo_desktop.customers c
   where c.owner_id=o and c.workspace_id=p_workspace and coalesce(c.data->>'registration_status','registered')='registered' and nullif(c.data->>'deleted_at','') is null and demo_desktop.sales_contact(o,p_workspace,c.id,year_value)->>'deleted_at' is null
   and not exists(select from demo_desktop.annual_work w where w.owner_id=o and w.workspace_id=p_workspace and w.customer_id=c.id and w.year=year_value and w.deleted_at is null)
   and not exists(select from demo_desktop.sales_assignments l where l.owner_id=o and l.workspace_id=p_workspace and l.customer_id=c.id and l.state<>'released') group by 1) r));
 elsif action='list-review' then
  return jsonb_build_object('rows',(select coalesce(jsonb_agg(jsonb_build_object('customerId',l.customer_id,'name',coalesce(c.data->>'name',''),'state',l.state,'lastSeenAt',l.last_seen_at,'responsible',coalesce(m.display_name,'사장님')) order by l.last_seen_at),'[]') from demo_desktop.sales_assignments l join demo_desktop.customers c on c.owner_id=l.owner_id and c.workspace_id=l.workspace_id and c.id=l.customer_id left join public.demo_members m on m.user_id=l.actor_id where l.owner_id=o and l.workspace_id=p_workspace and l.state='needs_review'));
 elsif action='claim' then
  if p_input ? 'nameQuery' and (jsonb_typeof(p_input->'nameQuery') is distinct from 'string' or char_length(p_input->>'nameQuery')>100) then perform demo_desktop.fail('invalid-input');end if;
  if jsonb_typeof(p_input->'region') is distinct from 'string' or char_length(p_input->>'region') not between 1 and 10000 then perform demo_desktop.fail('invalid-input');end if;
  region_value:=p_input->>'region';perform demo_desktop.sales_region_matches('{}'::jsonb,region_value);after_id:=(p_input->>'afterCustomerId')::bigint;direction_value:=coalesce(p_input->>'direction','next');if direction_value not in ('next','prev') then perform demo_desktop.fail('invalid-input');end if;
  select * into a from demo_desktop.sales_assignments where owner_id=o and workspace_id=p_workspace and actor_id=actor and session_id=p_session and state<>'released';
  if found then
   if not demo_desktop.sales_name_matches(demo_desktop.sales_contact(o,p_workspace,a.customer_id,year_value),coalesce(p_input->>'nameQuery','')) or a.auth_session_id<>login_session or a.service_year<>year_value or a.state<>'active' or not demo_desktop.sales_region_matches(demo_desktop.sales_contact(o,p_workspace,a.customer_id,year_value),region_value) then perform demo_desktop.fail('lease-unavailable');end if;
   return jsonb_build_object('row',demo_desktop.sales_contact(o,p_workspace,a.customer_id,year_value),'lease',demo_desktop.lease_json(a),'availableCount',demo_desktop.available_sales_count(o,p_workspace,year_value,region_value));
  end if;
  select c.id into cid from demo_desktop.customers c
  where c.owner_id=o and c.workspace_id=p_workspace and (after_id is null or c.id<>after_id) and coalesce(c.data->>'registration_status','registered')='registered' and nullif(c.data->>'deleted_at','') is null and demo_desktop.sales_contact(o,p_workspace,c.id,year_value)->>'deleted_at' is null
   and demo_desktop.sales_region_matches(demo_desktop.sales_contact(o,p_workspace,c.id,year_value),region_value)
   and demo_desktop.sales_name_matches(demo_desktop.sales_contact(o,p_workspace,c.id,year_value),coalesce(p_input->>'nameQuery',''))
   and not exists(select from demo_desktop.annual_work w where w.owner_id=o and w.workspace_id=p_workspace and w.customer_id=c.id and w.year=year_value and w.deleted_at is null)
   and not exists(select from demo_desktop.sales_assignments l where l.owner_id=o and l.workspace_id=p_workspace and l.customer_id=c.id and l.state<>'released')
  order by case when after_id is null then 0 when direction_value='prev' and c.id<after_id then 0 when direction_value='next' and c.id>after_id then 0 else 1 end,case when direction_value='prev' then -c.id else c.id end limit 1 for update;
  if cid is null then return jsonb_build_object('row',null,'lease',null,'availableCount',0);end if;
  insert into demo_desktop.sales_assignments(owner_id,workspace_id,customer_id,actor_id,auth_session_id,session_id,token,service_year,state,last_seen_at) values(o,p_workspace,cid,actor,login_session,p_session,gen_random_uuid(),year_value,'active',clock_timestamp())
  on conflict(owner_id,workspace_id,customer_id) do update set actor_id=excluded.actor_id,auth_session_id=excluded.auth_session_id,session_id=excluded.session_id,token=excluded.token,resume_from_token=null,service_year=excluded.service_year,state='active',last_seen_at=excluded.last_seen_at,created_at=clock_timestamp() returning * into a;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action) values(o,p_workspace,cid,actor,p_session,'claim');
  return jsonb_build_object('row',demo_desktop.sales_contact(o,p_workspace,cid,year_value),'lease',demo_desktop.lease_json(a),'availableCount',demo_desktop.available_sales_count(o,p_workspace,year_value,region_value));
 end if;
 cid:=(p_input->>'customerId')::bigint;token_value:=(p_input->>'token')::uuid;
 -- A completed original release is a receipt, never permission to release a newer token.
 if action in ('release','heartbeat','resume') and exists(select from demo_desktop.sales_audit receipt where receipt.owner_id=o and receipt.workspace_id=p_workspace and receipt.customer_id=cid and receipt.actor_id=actor and receipt.lease_token=token_value and receipt.action='release' and (receipt.session_id=p_session or p_input->>'action'='resume')) then
  if action='release' and p_input->'confirmedEnded' is distinct from 'true'::jsonb then perform demo_desktop.fail('invalid-input');end if;
  return jsonb_build_object('released',true,'row',null,'lease',null);
 end if;
 select * into a from demo_desktop.sales_assignments where owner_id=o and workspace_id=p_workspace and customer_id=cid for update;
 -- This response confirms only whether this exact session still owns its token.
 -- It never exposes or releases the replacement assignment.
 if action='confirm' then
  return jsonb_build_object('lost',a.customer_id is null or a.state='released' or a.actor_id<>actor or a.auth_session_id<>login_session or a.session_id<>p_session or a.token is distinct from token_value);
 end if;
 if not found or a.state='released' then perform demo_desktop.fail('lease-unavailable');end if;
 if action='admin-release' then
  reason_value:=demo_desktop.text_value(p_input,'reason',200);if reason_value is null then perform demo_desktop.fail('invalid-input');end if;
  update demo_desktop.sales_assignments set state='released',token=gen_random_uuid(),resume_from_token=null where owner_id=o and workspace_id=p_workspace and customer_id=cid;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action,reason) values(o,p_workspace,cid,actor,p_session,action,reason_value);
  return jsonb_build_object('released',true);
 end if;
 -- Replay requires the original desktop identity and token. A new login may
 -- recover it only after the original authentication session was revoked.
 if action='resume' and a.resume_from_token=token_value and a.actor_id=actor and a.session_id=p_session and (a.auth_session_id=login_session or (a.state='needs_review' and not exists(select from auth.sessions s where s.id=a.auth_session_id and s.user_id=actor))) then
  if not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is null and coalesce(data->>'registration_status','registered')='registered') or exists(select from demo_desktop.annual_work where owner_id=o and workspace_id=p_workspace and customer_id=cid and year=a.service_year and deleted_at is null) then perform demo_desktop.fail('lease-unavailable');end if;
  update demo_desktop.sales_assignments set state='active',auth_session_id=login_session,last_seen_at=clock_timestamp() where owner_id=o and workspace_id=p_workspace and customer_id=cid returning * into a;
  return jsonb_build_object('row',demo_desktop.sales_contact(o,p_workspace,cid,a.service_year),'lease',demo_desktop.lease_json(a),'availableCount',0);
 end if;
 if a.actor_id<>actor or a.token is distinct from token_value then perform demo_desktop.fail('lease-unavailable');end if;
 if action='resume' then
  if (a.state='active' and (a.session_id<>p_session or a.auth_session_id<>login_session)) or exists(select from demo_desktop.sales_assignments where owner_id=o and workspace_id=p_workspace and actor_id=actor and session_id=p_session and state<>'released' and customer_id<>cid) then perform demo_desktop.fail('lease-unavailable');end if;
  if not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is null and coalesce(data->>'registration_status','registered')='registered') or exists(select from demo_desktop.annual_work where owner_id=o and workspace_id=p_workspace and customer_id=cid and year=a.service_year and deleted_at is null) then perform demo_desktop.fail('lease-unavailable');end if;
  update demo_desktop.sales_assignments set state='active',auth_session_id=login_session,session_id=p_session,resume_from_token=token_value,token=gen_random_uuid(),last_seen_at=clock_timestamp() where owner_id=o and workspace_id=p_workspace and customer_id=cid returning * into a;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action) values(o,p_workspace,cid,actor,p_session,'resume');
 elsif a.session_id<>p_session or a.auth_session_id<>login_session then perform demo_desktop.fail('lease-unavailable');
 elsif action='heartbeat' then
  if a.state='active' then
   if not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=cid and nullif(data->>'deleted_at','') is null and coalesce(data->>'registration_status','registered')='registered') then perform demo_desktop.fail('lease-unavailable');end if;
   update demo_desktop.sales_assignments set last_seen_at=clock_timestamp() where owner_id=o and workspace_id=p_workspace and customer_id=cid returning * into a;
  end if;
 elsif action='release' then
  if p_input->'confirmedEnded' is distinct from 'true'::jsonb then perform demo_desktop.fail('invalid-input');end if;
  update demo_desktop.sales_assignments set state='released',token=gen_random_uuid(),resume_from_token=null where owner_id=o and workspace_id=p_workspace and customer_id=cid;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action,lease_token) values(o,p_workspace,cid,actor,p_session,'release',token_value);return jsonb_build_object('released',true);
 else perform demo_desktop.fail('invalid-input');end if;
 return jsonb_build_object('row',case when a.state='active' then demo_desktop.sales_contact(o,p_workspace,cid,a.service_year) else null end,'lease',demo_desktop.lease_json(a),'availableCount',0);
end $$;
create or replace function demo_desktop.save_sales(p_owner uuid,p_workspace uuid,p_session uuid,p_input jsonb) returns jsonb language plpgsql set search_path='' as $$
declare cid bigint:=(p_input->>'customerId')::bigint;year_value integer;token_value uuid:=(p_input->>'leaseToken')::uuid;context_value text:=coalesce(p_input->>'context','sales');r jsonb;c jsonb;v jsonb;amount bigint;task demo_desktop.annual_work;assignment demo_desktop.sales_assignments;status_value text:=p_input->>'status';deadline_value text;gid bigint;begin
 if p_input-array['type','context','key','year','customerId','revision','status','requirements','notes','deadline','currentAmount','leaseToken']<>'{}' or context_value not in ('sales','work') or jsonb_typeof(p_input->'year') is distinct from 'number' or (p_input->>'year')::numeric not between 1 and 9999 or (p_input->>'year')::numeric<>trunc((p_input->>'year')::numeric) or status_value is null or status_value not in ('uncontacted','proceed','declined') or jsonb_typeof(p_input->'notes') is distinct from 'string' or jsonb_typeof(p_input->'deadline') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
 year_value:=(p_input->>'year')::int;r:=demo_desktop.sales_contact(p_owner,p_workspace,cid,year_value);gid:=(r->>'graveId')::bigint;
 if r is null or r->>'revision' is distinct from p_input->>'revision' or r->>'deleted_at' is not null or (context_value='work' and r->>'workDeletedAt' is not null) then perform demo_desktop.fail('conflict');end if;
 select data into c from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid;
 if coalesce(c->>'registration_status','registered')<>'registered' then perform demo_desktop.fail('conflict');end if;
 select * into task from demo_desktop.annual_work where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid and year=year_value;
 if context_value='work' then
  if task.id is null or p_input->>'key' is distinct from 'annual:'||task.id then perform demo_desktop.fail('conflict');end if;
  perform demo_desktop.assert_editable(p_owner,p_workspace,p_session,cid);
 else
  select * into assignment from demo_desktop.sales_assignments where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid;
  if assignment.customer_id is null or (task.id is not null and task.deleted_at is null) or assignment.state<>'active' or assignment.service_year<>year_value or assignment.actor_id<>auth.uid() or assignment.auth_session_id<>demo_desktop.auth_session() or assignment.session_id<>p_session or assignment.token is distinct from token_value or assignment.last_seen_at<=clock_timestamp()-interval '90 seconds' then perform demo_desktop.fail('lease-unavailable');end if;
 end if;
 v:=demo_desktop.edit_values(jsonb_build_object('specialNotes',p_input->>'notes')||case when p_input ? 'requirements' then jsonb_build_object('requirements',p_input->'requirements') else '{}'::jsonb end,c);
 deadline_value:=coalesce(demo_desktop.text_value(p_input,'deadline',200),'');
 if (status_value='proceed' or nullif(p_input->>'currentAmount','') is not null) and gid is null then perform demo_desktop.fail('invalid-input');end if;
 if p_input ? 'currentAmount' then
  amount:=demo_desktop.number_value(p_input,'currentAmount');
  if amount is null and exists(select from demo_desktop.payments where owner_id=p_owner and workspace_id=p_workspace and grave_id=gid and year=year_value and kind='annual') then perform demo_desktop.fail('invalid-input');end if;
 end if;
 update demo_desktop.customers set data=data||jsonb_build_object('special_notes',v->'specialNotes')||case when p_input ? 'requirements' then jsonb_build_object('memo',v->'requirements') else '{}'::jsonb end where owner_id=p_owner and workspace_id=p_workspace and id=cid;
 if task.id is null then
  insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,data) values(p_owner,p_workspace,gen_random_uuid(),year_value,cid,gid,status_value,jsonb_build_object('notes',coalesce(v->>'specialNotes',''),'deadline',deadline_value));
 else update demo_desktop.annual_work a set deleted_at=null,grave_id=gid,status=status_value,data=a.data||jsonb_build_object('notes',coalesce(v->>'specialNotes',''),'deadline',deadline_value),version=a.version+1 where a.owner_id=p_owner and a.workspace_id=p_workspace and a.id=task.id;end if;
 if amount is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,year_value,'annual',amount,'desktop_sales');end if;
 perform demo_desktop.bump(p_owner,p_workspace,cid,gid);
 if context_value='sales' then
  update demo_desktop.sales_assignments set state='released',token=gen_random_uuid(),resume_from_token=null where owner_id=p_owner and workspace_id=p_workspace and customer_id=cid;
  insert into demo_desktop.sales_audit(owner_id,workspace_id,customer_id,actor_id,session_id,action) values(p_owner,p_workspace,cid,auth.uid(),p_session,'save');
 end if;
 return jsonb_build_object('customerId',cid,'graveId',gid,'year',year_value);
end $$;
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;
revoke all on function public.demo_sales_assignment(uuid,uuid,jsonb) from public,anon,service_role;
grant execute on function public.demo_sales_assignment(uuid,uuid,jsonb) to authenticated;

-- Immutable source bytes and an explicit previous server revision bind the one-time owner import.
create table if not exists demo_desktop.imported_earth_versions(owner_id uuid not null,workspace_id uuid not null,version_id uuid not null,grave_id bigint not null,data jsonb not null,primary key(owner_id,workspace_id,version_id),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id));
alter table demo_desktop.imported_earth_versions enable row level security;
revoke all on demo_desktop.imported_earth_versions from public,anon,authenticated,service_role,demo_desktop_writer;
create or replace function demo_desktop.import_id(p_row jsonb,p_field text) returns bigint language plpgsql immutable set search_path='' as $$declare v numeric;begin
 if jsonb_typeof(p_row->p_field) is distinct from 'number' then perform demo_desktop.fail('invalid-input');end if;v:=(p_row->>p_field)::numeric;
 if v<1 or v>9007199254740991 or v<>trunc(v) then perform demo_desktop.fail('invalid-input');end if;return v::bigint;
end $$;
create or replace function public.demo_desktop_import(p_workspace uuid,p_request uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);a uuid:=auth.uid();source jsonb;row_value jsonb;previous demo_desktop.requests;fingerprint text;result jsonb;server_revision text;k text;maximum bigint;counter bigint;cid bigint;gid bigint;event_value public.demo_events;begin
 if a<>o then perform demo_desktop.fail('access-denied');end if;
 if p_request is null or jsonb_typeof(p_input) is distinct from 'object' or p_input-array['sourceJson','sourceSha256','serverRevision']<>'{}' or jsonb_typeof(p_input->'sourceJson') is distinct from 'string' or octet_length(p_input->>'sourceJson')>20000000 or coalesce(p_input->>'sourceSha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_input->'serverRevision') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
 if encode(sha256(convert_to(p_input->>'sourceJson','UTF8')),'hex')<>p_input->>'sourceSha256' then perform demo_desktop.fail('source-mismatch');end if;
 begin source:=(p_input->>'sourceJson')::jsonb;exception when others then perform demo_desktop.fail('invalid-input');end;
 if jsonb_typeof(source) is distinct from 'object' or source-array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','idCounters','events']<>'{}' or jsonb_typeof(source->'idCounters') is distinct from 'object' then perform demo_desktop.fail('invalid-input');end if;
 foreach k in array array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','events'] loop if jsonb_typeof(source->k) is distinct from 'array' then perform demo_desktop.fail('invalid-input');end if;end loop;
 select revision into server_revision from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 perform demo_desktop.lock_actor(p_workspace,o);
 fingerprint:=encode(sha256(convert_to('import:'||p_input::text,'UTF8')),'hex');
 select * into previous from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=a and request_id=p_request;
 if found then
  if previous.input_sha<>fingerprint then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'result',previous.result,'snapshot',demo_desktop.snapshot(o,p_workspace));
 end if;
 if exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active) then perform demo_desktop.fail('already-shared');end if;
 if server_revision is distinct from p_input->>'serverRevision' then perform demo_desktop.fail('conflict');end if;
 insert into demo_desktop.companies(owner_id,workspace_id,active,source_revision,source_sha256) values(o,p_workspace,false,server_revision,p_input->>'sourceSha256') on conflict(owner_id,workspace_id) do update set source_revision=excluded.source_revision,source_sha256=excluded.source_sha256;
 if exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace) or exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace) then perform demo_desktop.fail('conflict');end if;
 for row_value in select value from jsonb_array_elements(source->'customers') loop
  cid:=demo_desktop.import_id(row_value,'id');
  if row_value-array['id','name','phone','phone_raw','phone_ok','memo','special_notes','registration_status','deleted_at','created_at']<>'{}' or coalesce(row_value->>'registration_status','registered') not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(o,p_workspace,cid,row_value-'id');
 end loop;
 for row_value in select value from jsonb_array_elements(source->'graves') loop
  gid:=demo_desktop.import_id(row_value,'id');cid:=case when row_value->>'customer_id' is not null then demo_desktop.import_id(row_value,'customer_id') end;
  if row_value-array['id','customer_id','address','gubun','seq','contract_year','gisu','pyeong','note','is_managed','business_region','extra_json','is_active','source_row','deleted_at','created_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(o,p_workspace,gid,cid,row_value-array['id','customer_id']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'payments') loop
  if row_value-array['id','grave_id','year','amount','kind','paid_at','method','source','note']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.payments(owner_id,workspace_id,id,grave_id,year,kind,amount,data) values(o,p_workspace,demo_desktop.import_id(row_value,'id'),demo_desktop.import_id(row_value,'grave_id'),(row_value->>'year')::integer,row_value->>'kind',(row_value->>'amount')::bigint,row_value-array['id','grave_id','year','kind','amount']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'annualWork') loop
  if row_value-array['id','year','customer_id','grave_id','status','notes','deadline','version','deleted_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'grave_id' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'grave_id')::bigint and customer_id=(row_value->>'customer_id')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,version,deleted_at,data) values(o,p_workspace,(row_value->>'id')::uuid,(row_value->>'year')::integer,demo_desktop.import_id(row_value,'customer_id'),case when row_value->>'grave_id' is not null then demo_desktop.import_id(row_value,'grave_id') end,row_value->>'status',coalesce((row_value->>'version')::bigint,1),row_value->>'deleted_at',row_value-array['id','year','customer_id','grave_id','status','version','deleted_at']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'workRows') loop
  if coalesce(row_value->>'key','')='' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'customerId' is not null and not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=(row_value->>'customerId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'graveId' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint and (row_value->>'customerId' is null or customer_id=(row_value->>'customerId')::bigint)) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.work_rows values(o,p_workspace,row_value->>'key',row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'locations') loop insert into demo_desktop.locations values(o,p_workspace,demo_desktop.import_id(row_value,'id'),row_value);end loop;
 for row_value in select value from jsonb_array_elements(source->'earthVersions') loop
  if row_value->'manifest'->>'workspaceId' is distinct from p_workspace::text or row_value->'manifest'->>'versionId' is distinct from row_value->>'versionId' or row_value->'manifest'->>'graveId' is distinct from row_value->>'graveId' or not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.imported_earth_versions values(o,p_workspace,(row_value->>'versionId')::uuid,demo_desktop.import_id(row_value,'graveId'),row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'earthLinks') loop
  if row_value->>'versionId' is not null and not exists(select from demo_desktop.imported_earth_versions where owner_id=o and workspace_id=p_workspace and version_id=(row_value->>'versionId')::uuid and grave_id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'versionId' is not null then
   if not exists(select from public.demo_earth_assets a join demo_desktop.imported_earth_versions v on v.owner_id=a.owner_id and v.workspace_id=a.workspace_id and v.version_id=a.version_id where a.owner_id=o and a.workspace_id=p_workspace and a.version_id=(row_value->>'versionId')::uuid and a.state='ready' and a.retired_at is null and a.manifest=v.data->'manifest') then perform demo_desktop.fail('earth-not-ready');end if;
   row_value:=jsonb_set(row_value,'{summary,asset}',(select jsonb_build_object('versionId',v.version_id,'sha256',v.data->'manifest'->'sha256','size',v.data->'manifest'->'size','sourceFile',v.data->'manifest'->'sourceFile','state','ready') from demo_desktop.imported_earth_versions v where v.owner_id=o and v.workspace_id=p_workspace and v.version_id=(row_value->>'versionId')::uuid));
  end if;
  insert into demo_desktop.earth_links values(o,p_workspace,demo_desktop.import_id(row_value,'graveId'),(row_value->>'versionId')::uuid,row_value->'summary');
 end loop;
 foreach k in array array['customers','graves','payments'] loop
  execute format('select coalesce(max(id),0) from demo_desktop.%I where owner_id=$1 and workspace_id=$2',k) into maximum using o,p_workspace;
  if jsonb_typeof(source->'idCounters'->k) is distinct from 'number' or (source->'idCounters'->>k)::numeric<>trunc((source->'idCounters'->>k)::numeric) then perform demo_desktop.fail('invalid-input');end if;
  counter:=(source->'idCounters'->>k)::bigint;if counter<maximum or counter>9007199254740991 then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.id_counters values(o,p_workspace,k,counter) on conflict(owner_id,workspace_id,name) do update set high_water=greatest(demo_desktop.id_counters.high_water,excluded.high_water);
 end loop;
 -- Events remain additive and keep their original IDs. Current customer changes never rewrite history.
 for row_value in select value from jsonb_array_elements(source->'events') order by case value->>'kind' when 'claim_created' then 0 else 1 end,value->>'at',value->>'id' loop
  if row_value->>'workspaceId' is distinct from p_workspace::text then perform demo_desktop.fail('invalid-input');end if;
  select * into event_value from public.demo_events where owner_id=o and id=(row_value->>'id')::uuid;
  if found then
   if event_value.workspace_id<>p_workspace or event_value.kind is distinct from row_value->>'kind' or event_value.payload is distinct from row_value->'payload' or event_value.happened_at is distinct from (row_value->>'at')::timestamptz then perform demo_desktop.fail('conflict');end if;
  else insert into public.demo_events(owner_id,workspace_id,id,kind,happened_at,payload) values(o,p_workspace,(row_value->>'id')::uuid,row_value->>'kind',(row_value->>'at')::timestamptz,row_value->'payload');end if;
 end loop;
 update demo_desktop.companies set active=true where owner_id=o and workspace_id=p_workspace;
 if to_regprocedure('demo_desktop.refresh_sent_amounts(uuid,uuid)') is not null then perform demo_desktop.refresh_sent_amounts(o,p_workspace);end if;
 perform demo_desktop.refresh_projection(o,p_workspace);
 result:=jsonb_build_object('imported',true,'sourceSha256',p_input->>'sourceSha256','serverRevision',p_input->>'serverRevision');
 insert into demo_desktop.requests values(o,p_workspace,a,p_request,gen_random_uuid(),fingerprint,result,clock_timestamp());
 return jsonb_build_object('requestId',p_request,'result',result,'snapshot',demo_desktop.snapshot(o,p_workspace));
end $$;
create or replace function public.demo_desktop_read(p_workspace uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare o uuid:=demo_desktop.assert_actor(p_workspace);begin
 if exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active) then return demo_desktop.snapshot(o,p_workspace);end if;
 return jsonb_build_object('protocol',1,'mode','legacy','ownerId',o,'workspaceId',p_workspace,'revision',(select revision from public.demo_catalogs where owner_id=o and workspace_id=p_workspace));
end $$;
