create or replace function demo_desktop.allocation_catalog(o uuid,w uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 if exists(select from demo_desktop.companies where owner_id=o and workspace_id=w and active) then return demo_desktop.snapshot(o,w)->'catalog';end if;
 return (select payload from public.demo_catalogs where owner_id=o and workspace_id=w);
end $$;
create or replace function demo_desktop.allocation_rows(c jsonb,keys jsonb) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('key',r->>'key','address',coalesce(r->>'address',''),'sequence',coalesce(r->>'sequence',''),'number',coalesce(r->>'number',''),'rowNumber',k.pos) order by k.pos),'[]')
 from jsonb_array_elements(keys) with ordinality k(value,pos) join lateral (select value r from jsonb_array_elements(coalesce(c->'workRows','[]')) where value->>'key'=k.value#>>'{}' limit 1) x on true
 where nullif(r->>'deleted_at','') is null and coalesce(r->>'status','proceed')='proceed'
 and not exists(select from jsonb_array_elements(coalesce(c->'customers','[]')) p where (r->>'customerId'=p->>'id' and (nullif(p->>'deleted_at','') is not null or p->>'registration_status'='declined')) or exists(select from jsonb_array_elements(coalesce(p->'graves','[]')) g where g->>'id'=r->>'graveId' and (nullif(g->>'deleted_at','') is not null or nullif(p->>'deleted_at','') is not null or p->>'registration_status'='declined')))
 and not exists(select from jsonb_array_elements(coalesce(c->'unassignedGraves','[]')) g where g->>'id'=r->>'graveId' and nullif(g->>'deleted_at','') is not null);
$$;
create or replace function public.demo_desktop_work_allocations(p_workspace uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb:=public.demo_access(p_workspace);o uuid:=(a->>'ownerId')::uuid;actor uuid:=auth.uid();action text:=p_input->>'action';c jsonb;sheet jsonb;held demo_desktop.work_allocations;route demo_desktop.work_routes;rows jsonb;result jsonb;sha text;receipt demo_desktop.work_allocation_requests;member public.demo_members;rid uuid;members jsonb;shared boolean;begin
 perform demo_desktop.assert_schema();
 if not exists(select from auth.sessions where id=demo_desktop.auth_session() and user_id=actor) then perform demo_desktop.fail('access-denied');end if;
 if jsonb_typeof(p_input) is distinct from 'object' or p_input-array['action','requestId','sheets','userIds']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
 perform 1 from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 if not found then perform demo_desktop.fail('access-denied');end if;
 perform 1 from auth.sessions where id=demo_desktop.auth_session() and user_id=actor for key share;
 if not found then perform demo_desktop.fail('access-denied');end if;
 select * into member from public.demo_members where user_id=actor for share;
 if found and (not member.active or member.owner_id<>o or member.workspace_id<>p_workspace or member.role<>a->>'role') then perform demo_desktop.fail('access-denied');end if;
 if action='mine' then
  if a->>'role' not in ('worker','manager') then perform demo_desktop.fail('access-denied');end if;
  c:=demo_desktop.allocation_catalog(o,p_workspace);
  return jsonb_build_object('sheets',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',data->>'title','year',data->'year','version',version,'workKeys',data->'workKeys','rows',demo_desktop.allocation_rows(c,data->'workKeys'),'outdated',coalesce((data->>'outdated')::boolean,false) or data->>'rowHash' is distinct from md5(demo_desktop.allocation_rows(c,data->'workKeys')::text) or jsonb_array_length(demo_desktop.allocation_rows(c,data->'workKeys'))<>jsonb_array_length(data->'workKeys') or (data->'shared'='false'::jsonb and not exists(select from jsonb_array_elements(coalesce(c->'workSheets','[]')) r where r->>'id'=w.id::text and r->'version'=w.data->'routeVersion' and r->'valid'='true'::jsonb)) or (data->'shared'='true'::jsonb and not exists(select from demo_desktop.work_routes r where r.owner_id=o and r.workspace_id=p_workspace and r.id=w.id and r.version=(w.data->>'routeVersion')::bigint and r.data->'basis' is not distinct from demo_desktop.route_basis(o,p_workspace,r.year,r.data->>'regionFilter')))) order by data->>'title',id),'[]') from demo_desktop.work_allocations w where owner_id=o and workspace_id=p_workspace and data->'userIds' @> jsonb_build_array(actor::text)));
 end if;
 if a->>'role' not in ('owner','master') then perform demo_desktop.fail('access-denied');end if;
 if action='list' then
  select coalesce(jsonb_agg(jsonb_build_object('user_id',user_id,'display_name',display_name,'login_id',login_id,'role',role,'active',active) order by display_name,login_id),'[]') into members from public.demo_members where owner_id=o and workspace_id=p_workspace and active and role in ('worker','manager');
  return jsonb_build_object('members',members,'assignments',(select coalesce(jsonb_agg(data||jsonb_build_object('version',version) order by data->>'title',id),'[]') from demo_desktop.work_allocations where owner_id=o and workspace_id=p_workspace));
 end if;
 if action not in ('save','clear') or jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'sheets') is distinct from 'array' or jsonb_array_length(p_input->'sheets') not between 1 and 100 then perform demo_desktop.fail('invalid-input');end if;
 rid:=(p_input->>'requestId')::uuid;sha:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
 select * into receipt from demo_desktop.work_allocation_requests where owner_id=o and workspace_id=p_workspace and actor_id=actor and request_id=rid;
 if found then if receipt.input_sha<>sha then perform demo_desktop.fail('conflict');end if;return receipt.result;end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(p_input->'sheets'))<>jsonb_array_length(p_input->'sheets') then perform demo_desktop.fail('invalid-input');end if;
 if action='save' then
  if jsonb_typeof(p_input->'userIds') is distinct from 'array' or jsonb_array_length(p_input->'userIds') not between 1 and 100 or (select count(distinct value) from jsonb_array_elements(p_input->'userIds'))<>jsonb_array_length(p_input->'userIds') then perform demo_desktop.fail('invalid-input');end if;
  perform 1 from public.demo_members where owner_id=o and workspace_id=p_workspace and p_input->'userIds' @> jsonb_build_array(user_id::text) order by user_id for share;
  if exists(select from jsonb_array_elements(p_input->'userIds') u where jsonb_typeof(u)<>'string' or not exists(select from public.demo_members m where m.owner_id=o and m.workspace_id=p_workspace and m.user_id::text=u#>>'{}' and m.active and m.role in ('worker','manager'))) then perform demo_desktop.fail('invalid-input');end if;
 end if;
 c:=demo_desktop.allocation_catalog(o,p_workspace);shared:=exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active);
 for sheet in select value from jsonb_array_elements(p_input->'sheets') loop
  if jsonb_typeof(sheet) is distinct from 'object' or sheet-array['id','expectedVersion','routeVersion','title','year','workKeys']<>'{}' or jsonb_typeof(sheet->'expectedVersion') is distinct from 'number' or (sheet->>'expectedVersion')::numeric<0 or (sheet->>'expectedVersion')::numeric<>trunc((sheet->>'expectedVersion')::numeric) then perform demo_desktop.fail('invalid-input');end if;
  select * into held from demo_desktop.work_allocations where owner_id=o and workspace_id=p_workspace and id=(sheet->>'id')::uuid for update;
  if coalesce(held.version,0)<>(sheet->>'expectedVersion')::bigint then perform demo_desktop.fail('conflict');end if;
  if action='clear' then
   if held.id is null then perform demo_desktop.fail('conflict');end if;
   update demo_desktop.work_allocations set version=version+1,data=data||jsonb_build_object('userIds','[]'::jsonb,'updatedAt',clock_timestamp()::text) where owner_id=o and workspace_id=p_workspace and id=held.id;
  else
   if jsonb_typeof(sheet->'title') is distinct from 'string' or char_length(sheet->>'title') not between 1 and 1000 or jsonb_typeof(sheet->'year') is distinct from 'number' or (sheet->>'year')::numeric not between 1 and 9999 or (sheet->>'year')::numeric<>trunc((sheet->>'year')::numeric) or jsonb_typeof(sheet->'routeVersion') is distinct from 'number' or (sheet->>'routeVersion')::numeric<1 or (sheet->>'routeVersion')::numeric<>trunc((sheet->>'routeVersion')::numeric) or jsonb_typeof(sheet->'workKeys') is distinct from 'array' or jsonb_array_length(sheet->'workKeys') not between 1 and 10000 then perform demo_desktop.fail('invalid-input');end if;
   if exists(select from jsonb_array_elements(sheet->'workKeys') k where jsonb_typeof(k)<>'string' or length(k#>>'{}') not between 1 and 200) or (select count(distinct value) from jsonb_array_elements(sheet->'workKeys'))<>jsonb_array_length(sheet->'workKeys') then perform demo_desktop.fail('invalid-input');end if;
   rows:=demo_desktop.allocation_rows(c,sheet->'workKeys');if jsonb_array_length(rows)<>jsonb_array_length(sheet->'workKeys') then perform demo_desktop.fail('conflict');end if;
   if shared then
    select * into route from demo_desktop.work_routes where owner_id=o and workspace_id=p_workspace and id=(sheet->>'id')::uuid;
    if route.id is null or route.year<>(sheet->>'year')::integer or route.version<>(sheet->>'routeVersion')::bigint or route.data->'workKeys' is distinct from sheet->'workKeys' or route.data->'basis' is distinct from demo_desktop.route_basis(o,p_workspace,route.year,route.data->>'regionFilter') then perform demo_desktop.fail('conflict');end if;
   elsif not exists(select from jsonb_array_elements(coalesce(c->'workSheets','[]')) r where r->>'id'=sheet->>'id' and r->'version'=sheet->'routeVersion' and r->'valid'='true'::jsonb) then perform demo_desktop.fail('conflict');
   end if;
   insert into demo_desktop.work_allocations(owner_id,workspace_id,id,version,data) values(o,p_workspace,(sheet->>'id')::uuid,coalesce(held.version,0)+1,(sheet-array['expectedVersion'])||jsonb_build_object('userIds',p_input->'userIds','shared',shared,'rowHash',md5(rows::text),'outdated',false,'updatedAt',clock_timestamp()::text)) on conflict(owner_id,workspace_id,id) do update set version=excluded.version,data=excluded.data;
  end if;
 end loop;
 insert into public.demo_sync_signals(owner_id,workspace_id,kind) values(o,p_workspace,'catalog') on conflict(owner_id,workspace_id,kind) do update set revision=public.demo_sync_signals.revision+1,updated_at=clock_timestamp();
 result:=jsonb_build_object('saved',true,'requestId',rid);
 insert into demo_desktop.work_allocation_requests values(o,p_workspace,actor,rid,sha,result);
 return result;
end $$;
create or replace function demo_desktop.prune_work_allocations() returns trigger language plpgsql security definer set search_path='' as $$declare p demo_desktop.work_allocations;c jsonb;keys jsonb;begin
 c:=demo_desktop.allocation_catalog(new.owner_id,new.workspace_id);
 for p in select * from demo_desktop.work_allocations where owner_id=new.owner_id and workspace_id=new.workspace_id loop
  select coalesce(jsonb_agg(value->'key' order by pos),'[]') into keys from jsonb_array_elements(demo_desktop.allocation_rows(c,p.data->'workKeys')) with ordinality r(value,pos);
  if keys is distinct from p.data->'workKeys' then update demo_desktop.work_allocations set version=version+1,data=data||jsonb_build_object('workKeys',keys,'outdated',true) where owner_id=p.owner_id and workspace_id=p.workspace_id and id=p.id;end if;
 end loop;return null;
end $$;
drop trigger if exists prune_work_allocations on public.demo_catalogs;
create trigger prune_work_allocations after update on public.demo_catalogs for each row execute function demo_desktop.prune_work_allocations();
revoke all on function demo_desktop.allocation_catalog(uuid,uuid),demo_desktop.allocation_rows(jsonb,jsonb),demo_desktop.prune_work_allocations() from public,anon,authenticated,service_role;
revoke all on function public.demo_desktop_work_allocations(uuid,jsonb) from public,anon,service_role;
grant execute on function public.demo_desktop_work_allocations(uuid,jsonb) to authenticated;

-- A report references the assigned work, never a client-supplied customer or an ambiguous address.
create table if not exists demo_desktop.report_work_links (
 report_id uuid primary key references public.demo_work_reports(id) on delete cascade,
 owner_id uuid not null, workspace_id uuid not null, sheet_id uuid not null,
 work_key text not null, customer_id bigint, grave_id bigint not null,
 foreign key(owner_id,workspace_id) references public.demo_catalogs(owner_id,workspace_id)
);
alter table demo_desktop.report_work_links enable row level security;
revoke all on demo_desktop.report_work_links from public,anon,authenticated,service_role,demo_desktop_writer;

create or replace function demo_desktop.assigned_work(o uuid,w uuid,actor uuid,sheet_id uuid,work_key text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a demo_desktop.work_allocations;c jsonb;r jsonb;g jsonb;p jsonb;customer jsonb;point jsonb;ordered jsonb;shared boolean;begin
 perform 1 from public.demo_members where user_id=actor and owner_id=o and workspace_id=w and active and role in ('worker','manager') for share;
 if not found then perform demo_desktop.fail('access-denied');end if;
 select * into a from demo_desktop.work_allocations where owner_id=o and workspace_id=w and id=sheet_id and data->'userIds' @> jsonb_build_array(actor::text) for share;
 if not found then perform demo_desktop.fail('access-denied');end if;
 c:=demo_desktop.allocation_catalog(o,w);ordered:=demo_desktop.allocation_rows(c,a.data->'workKeys');
 if coalesce((a.data->>'outdated')::boolean,false) or a.data->>'rowHash' is distinct from md5(ordered::text)
 or not a.data->'workKeys' @> jsonb_build_array(work_key) or jsonb_array_length(ordered)<>jsonb_array_length(a.data->'workKeys') then perform demo_desktop.fail('conflict');end if;
 shared:=a.data->'shared'='true'::jsonb;
 if shared then
  if not exists(select from demo_desktop.work_routes x where x.owner_id=o and x.workspace_id=w and x.id=sheet_id and x.version=(a.data->>'routeVersion')::bigint and x.data->'basis' is not distinct from demo_desktop.route_basis(o,w,x.year,x.data->>'regionFilter')) then perform demo_desktop.fail('conflict');end if;
 elsif not exists(select from jsonb_array_elements(coalesce(c->'workSheets','[]')) x where x->>'id'=sheet_id::text and x->'version'=a.data->'routeVersion' and x->'valid'='true'::jsonb) then perform demo_desktop.fail('conflict');end if;
 select value into r from jsonb_array_elements(c->'workRows') where value->>'key'=work_key;
 select value into customer from jsonb_array_elements(c->'customers') where value->>'id'=r->>'customerId' and exists(select from jsonb_array_elements(value->'graves') linked where linked->>'id'=r->>'graveId');
 select x into g from (
  select x from jsonb_array_elements(c->'customers') person cross join lateral jsonb_array_elements(person->'graves') x
  union all select x from jsonb_array_elements(coalesce(c->'unassignedGraves','[]')) x
 ) graves where x->>'id'=r->>'graveId';
 if g is null or nullif(g->>'deleted_at','') is not null or coalesce(r->>'address','')<>coalesce(g->>'address','') then perform demo_desktop.fail('conflict');end if;
 -- Only provider-independent KML or field/public-parcel coordinates may be displayed on Kakao.
 if g->'earth'->>'source'='google_earth_kml' and g->'earth'->>'originalAddress'=g->>'address' then point:=g->'earth'->'point';end if;
 if shared then
  select data->'location' into p from demo_desktop.locations where owner_id=o and workspace_id=w and grave_id=(g->>'id')::bigint and data->>'address'=g->>'address' and data->'location'->>'source' in ('field','public_parcel');
 else
  select value->'location' into p from public.demo_map_snapshots s cross join lateral jsonb_array_elements(s.payload->'locations') where s.owner_id=o and s.workspace_id=w and value->>'id'=g->>'id' and value->>'address'=g->>'address' and value->'location'->>'source' in ('field','public_parcel');
 end if;
 if p->>'source'='field' or point is null then point:=p;end if;
 if jsonb_typeof(point->'lat')<>'number' or jsonb_typeof(point->'lng')<>'number' or abs((point->>'lat')::numeric)>90 or abs((point->>'lng')::numeric)>180 then point:=null;end if;
 return jsonb_build_object('detail',jsonb_build_object('sheetId',sheet_id,'workKey',work_key,'title',a.data->'title','order',(select value->'rowNumber' from jsonb_array_elements(ordered) where value->>'key'=work_key),'address',g->>'address','requirements',coalesce(customer->>'memo',''),'specialNotes',coalesce(customer->>'special_notes',''),'location',case when point is null then null else jsonb_build_object('lat',point->'lat','lng',point->'lng','source',coalesce(point->>'source','google_earth_kml')) end),'customerId',r->'customerId','graveId',g->'id');
end $$;

create or replace function demo_desktop.report_view(p public.demo_work_reports) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('id',p.id,'owner_id',p.owner_id,'workspace_id',p.workspace_id,'reporter_id',p.reporter_id,'reporter_name',p.reporter_name,'location',p.location,'photos',(select coalesce(jsonb_agg(jsonb_build_object('id',x->'id','size',x->'size')),'[]') from jsonb_array_elements(p.photos) x),'total_bytes',p.total_bytes,'state',p.state,'created_at',p.created_at,'published_at',p.published_at,'photo_state',p.photo_state,'desktop_archived_at',p.desktop_archived_at,'activity_updated_at',p.activity_updated_at)
 ||coalesce((select jsonb_build_object('assignment',jsonb_build_object('sheetId',l.sheet_id,'workKey',l.work_key))
 ||case when auth.uid()=p.owner_id or exists(select from public.demo_members m where m.user_id=auth.uid() and m.owner_id=p.owner_id and m.workspace_id=p.workspace_id and m.active and m.role in ('owner','master','manager'))
 then jsonb_build_object('workLink',jsonb_build_object('customerId',l.customer_id,'graveId',l.grave_id,'workKey',l.work_key)) else '{}'::jsonb end
 from demo_desktop.report_work_links l where l.report_id=p.id and l.owner_id=p.owner_id and l.workspace_id=p.workspace_id),'{}'::jsonb)
$$;

create or replace function public.demo_assigned_work(p_workspace uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb:=public.demo_access(p_workspace);o uuid:=(a->>'ownerId')::uuid;task jsonb;r public.demo_work_reports;link demo_desktop.report_work_links;n bigint;capacity bigint;p jsonb;begin
 perform demo_desktop.transfer_keys(p_input,array['action','sheetId','workKey','id','photos','location']);
 perform 1 from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 if demo_desktop.privacy_enabled(o,p_workspace) then perform demo_desktop.lock_company(o,p_workspace);end if;
 perform demo_desktop.lock_privacy_actor(p_workspace,o);
 if p_input->>'action'='authorize' then
  select * into r from public.demo_work_reports where id=(p_input->>'id')::uuid and owner_id=o and workspace_id=p_workspace and reporter_id=auth.uid();
  select * into link from demo_desktop.report_work_links where report_id=r.id and owner_id=o and workspace_id=p_workspace;
  if link.report_id is null or not demo_desktop.report_visible(o,p_workspace,r.id) then perform demo_desktop.fail('access-denied');end if;
  perform demo_desktop.assigned_work(o,p_workspace,auth.uid(),link.sheet_id,link.work_key);return jsonb_build_object('allowed',true);
 end if;
 if jsonb_typeof(p_input->'workKey') is distinct from 'string' or length(p_input->>'workKey') not between 1 and 200 then perform demo_desktop.fail('invalid-input');end if;
 task:=demo_desktop.assigned_work(o,p_workspace,auth.uid(),(p_input->>'sheetId')::uuid,p_input->>'workKey');
 if p_input->>'action'='detail' then return task->'detail';end if;
 if p_input->>'action' is distinct from 'reserve' then perform demo_desktop.fail('invalid-input');end if;
 if p_input->>'location' is distinct from task->'detail'->>'address' then perform demo_desktop.fail('conflict');end if;
 if char_length(trim(task->'detail'->>'address')) not between 1 and 200 or jsonb_typeof(p_input->'photos') is distinct from 'array' or jsonb_array_length(p_input->'photos') not between 1 and 10 then perform demo_desktop.fail('invalid-input');end if;
 n:=0;
 for p in select value from jsonb_array_elements(p_input->'photos') loop
  if jsonb_typeof(p) is distinct from 'object' or p-array['id','size']<>'{}' or not(p ?& array['id','size']) or jsonb_typeof(p->'size') is distinct from 'number' or (p->>'size')!~'^[0-9]+$' or (p->>'size')::bigint not between 1 and 1000000 or (p->>'id')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then perform demo_desktop.fail('invalid-input');end if;n:=n+(p->>'size')::bigint;
 end loop;
 if (select count(distinct value->>'id') from jsonb_array_elements(p_input->'photos'))<>jsonb_array_length(p_input->'photos') then perform demo_desktop.fail('invalid-input');end if;
 select limit_bytes into capacity from public.demo_photo_budget where id=true for update;
 select * into r from public.demo_work_reports where id=(p_input->>'id')::uuid;
 if found then
  select * into link from demo_desktop.report_work_links where report_id=r.id;
  if r.owner_id<>o or r.workspace_id<>p_workspace or r.reporter_id is distinct from auth.uid() or r.location<>p_input->>'location' or r.photos<>p_input->'photos' or link.sheet_id is distinct from (p_input->>'sheetId')::uuid or link.work_key is distinct from p_input->>'workKey' or link.grave_id is distinct from (task->>'graveId')::bigint or not demo_desktop.report_visible(o,p_workspace,r.id) then perform demo_desktop.fail('conflict');end if;
  return demo_desktop.report_view(r);
 end if;
 if capacity is null or (select coalesce(sum(total_bytes),0) from public.demo_work_reports)+n>capacity then raise exception 'Storage limit reached';end if;
 insert into public.demo_work_reports(id,owner_id,workspace_id,reporter_id,reporter_name,location,photos,total_bytes)
 values((p_input->>'id')::uuid,o,p_workspace,auth.uid(),a->>'displayName',task->'detail'->>'address',p_input->'photos',n) returning * into r;
 insert into demo_desktop.report_work_links values(r.id,o,p_workspace,(p_input->>'sheetId')::uuid,p_input->>'workKey',(task->>'customerId')::bigint,(task->>'graveId')::bigint);
 if demo_desktop.privacy_enabled(o,p_workspace) then insert into demo_desktop.privacy_media(owner_id,workspace_id,kind,asset_id,grave_id,state,record_sha256,photos) values(o,p_workspace,'report',r.id,(task->>'graveId')::bigint,'active',demo_desktop.financial_digest(jsonb_build_object('id',r.id,'photos',r.photos,'location',r.location,'reporterId',r.reporter_id)),r.photos);end if;
 return demo_desktop.report_view(r);
end $$;

-- Called only after the Edge Function has checked every uploaded R2 object.
create or replace function public.demo_publish_assigned_report(p_owner uuid,p_workspace uuid,p_actor uuid,p_session uuid,p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.demo_work_reports;l demo_desktop.report_work_links;begin
 perform 1 from public.demo_catalogs where owner_id=p_owner and workspace_id=p_workspace for no key update;
 if demo_desktop.privacy_enabled(p_owner,p_workspace) then perform demo_desktop.lock_company(p_owner,p_workspace);end if;
 perform demo_desktop.media_actor(p_owner,p_workspace,p_actor,p_session,false);
 select * into r from public.demo_work_reports where id=p_id and owner_id=p_owner and workspace_id=p_workspace and reporter_id=p_actor for update;
 select * into l from demo_desktop.report_work_links where report_id=r.id and owner_id=p_owner and workspace_id=p_workspace;
 if l.report_id is null or not demo_desktop.report_visible(p_owner,p_workspace,p_id) then perform demo_desktop.fail('access-denied');end if;
 perform demo_desktop.assigned_work(p_owner,p_workspace,p_actor,l.sheet_id,l.work_key);
 if r.state<>'ready' then
  perform 1 from public.demo_photo_budget where id=true for update;
  update public.demo_work_reports set state='ready',published_at=clock_timestamp(),retention_key='grave:'||l.grave_id where id=p_id;
  with ranked as (select id,row_number() over(order by published_at desc,id desc) n from public.demo_work_reports where owner_id=p_owner and workspace_id=p_workspace and retention_key='grave:'||l.grave_id and state='ready')
  update public.demo_work_reports set photo_state='pruning' where id in(select id from ranked where n>2) and photo_state='active';
 end if;
 return jsonb_build_object('state','ready');
end $$;
revoke all on function demo_desktop.assigned_work(uuid,uuid,uuid,uuid,text),demo_desktop.report_view(public.demo_work_reports) from public,anon,authenticated,service_role;
revoke all on function public.demo_assigned_work(uuid,jsonb) from public,anon,service_role;
grant execute on function public.demo_assigned_work(uuid,jsonb) to authenticated;
revoke all on function public.demo_publish_assigned_report(uuid,uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.demo_publish_assigned_report(uuid,uuid,uuid,uuid,uuid) to service_role;

-- Preserve the existing privacy lifecycle for reports linked directly to assigned work.
create or replace function demo_desktop.register_private_media(p_owner uuid,p_workspace uuid,p_operation uuid) returns void language plpgsql set search_path='' as $$declare s demo_desktop.privacy_subjects;r public.demo_earth_assets;b public.demo_work_reports;candidate demo_desktop.earth_candidates;known boolean;affected boolean;shared boolean;media_state text;begin
 perform demo_desktop.lock_company(p_owner,p_workspace);
 if p_operation is not null then select * into s from demo_desktop.privacy_subjects where operation_id=p_operation and owner_id=p_owner and workspace_id=p_workspace;if not found then perform demo_desktop.fail('invalid-input');end if;if s.customer_id is null and cardinality(s.grave_ids)=0 then return;end if;end if;
 for r in select * from public.demo_earth_assets where owner_id=p_owner and workspace_id=p_workspace and (p_operation is null or (manifest->>'graveId')::bigint=any(s.grave_ids)) loop
  insert into demo_desktop.privacy_media(owner_id,workspace_id,kind,asset_id,operation_id,grave_id,classification,state,sha256,name_sha256,extension,size,record_sha256)
  values(p_owner,p_workspace,'asset',r.version_id,p_operation,(r.manifest->>'graveId')::bigint,'unclassified',case when p_operation is null then 'active' else 'retired' end,r.manifest->>'sha256',demo_desktop.financial_digest(to_jsonb(lower(normalize(r.manifest->>'sourceFile',NFC)))),case when r.manifest->>'sourceFile'~*'\.kmz$' then 'kmz' else 'kml' end,(r.manifest->>'size')::bigint,demo_desktop.financial_digest(r.manifest))
  on conflict(owner_id,workspace_id,kind,asset_id) do update set operation_id=coalesce(demo_desktop.privacy_media.operation_id,excluded.operation_id),state=case when excluded.operation_id is not null and demo_desktop.privacy_media.state<>'cleaned' then 'retired' else demo_desktop.privacy_media.state end,eligible_at=case when excluded.operation_id is not null and demo_desktop.privacy_media.state='active' then clock_timestamp()+interval '6 minutes' else demo_desktop.privacy_media.eligible_at end,version=demo_desktop.privacy_media.version+1;
  if p_operation is not null then
   perform demo_desktop.asset_write(p_owner,p_workspace,r.created_by,null,r.version_id,'retire');
   insert into demo_desktop.privacy_cleanup_jobs(operation_id,owner_id,workspace_id,kind,target_key,state,reason_code) values(p_operation,p_owner,p_workspace,'asset',r.version_id::text,'blocked','policy-review') on conflict do nothing;
  end if;
 end loop;
 for candidate in select c.* from demo_desktop.earth_candidates c where c.owner_id=p_owner and c.workspace_id=p_workspace and (p_operation is null or c.grave_id=any(s.grave_ids)) and not exists(select from demo_desktop.privacy_media m where m.owner_id=p_owner and m.workspace_id=p_workspace and m.kind='asset' and m.asset_id=c.version_id) loop
  insert into demo_desktop.privacy_media(owner_id,workspace_id,kind,asset_id,operation_id,grave_id,customer_id,state,sha256,name_sha256,extension,size,record_sha256)
  values(p_owner,p_workspace,'asset',candidate.version_id,p_operation,candidate.grave_id,candidate.customer_id,case when p_operation is null then 'active' else 'retired' end,candidate.manifest->>'sha256',demo_desktop.financial_digest(to_jsonb(lower(normalize(candidate.manifest->>'sourceFile',NFC)))),case when candidate.manifest->>'sourceFile'~*'\.kmz$' then 'kmz' else 'kml' end,(candidate.manifest->>'size')::bigint,demo_desktop.financial_digest(candidate.manifest));
  if p_operation is not null then insert into demo_desktop.privacy_cleanup_jobs(operation_id,owner_id,workspace_id,kind,target_key,state,reason_code) values(p_operation,p_owner,p_workspace,'asset',candidate.version_id::text,'blocked','policy-review') on conflict do nothing;end if;
 end loop;
 for b in select * from public.demo_work_reports where owner_id=p_owner and workspace_id=p_workspace loop
  select exists(select from public.demo_events e where e.owner_id=p_owner and e.workspace_id=p_workspace and e.kind='claim_created' and e.payload->>'reportId'=b.id::text) into known;
  select exists(select from public.demo_events e where e.owner_id=p_owner and e.workspace_id=p_workspace and e.kind='claim_created' and e.payload->>'reportId'=b.id::text and exists(select from demo_desktop.privacy_subjects x where x.owner_id=p_owner and x.workspace_id=p_workspace and ((e.payload->>'customerId')::bigint=x.customer_id or (e.payload->>'graveId')::bigint=any(x.grave_ids)))) into affected;
  select exists(select from public.demo_events e join demo_desktop.customers c on c.owner_id=e.owner_id and c.workspace_id=e.workspace_id and c.id=(e.payload->>'customerId')::bigint where e.owner_id=p_owner and e.workspace_id=p_workspace and e.kind='claim_created' and e.payload->>'reportId'=b.id::text and nullif(c.data->>'deleted_at','') is null and coalesce(c.data->>'registration_status','registered')<>'declined' and not exists(select from demo_desktop.privacy_subjects x where x.owner_id=p_owner and x.workspace_id=p_workspace and (x.customer_id=c.id or (e.payload->>'graveId')::bigint=any(x.grave_ids)))) into shared;
  -- Assigned work is an exact link even before the first billing claim exists.
  known:=known or exists(select from demo_desktop.report_work_links l where l.report_id=b.id and l.owner_id=p_owner and l.workspace_id=p_workspace);
  affected:=affected or exists(select from demo_desktop.report_work_links l join demo_desktop.privacy_subjects x on x.owner_id=l.owner_id and x.workspace_id=l.workspace_id and (x.customer_id=l.customer_id or l.grave_id=any(x.grave_ids)) where l.report_id=b.id and l.owner_id=p_owner and l.workspace_id=p_workspace);
  shared:=shared or exists(select from demo_desktop.report_work_links l join demo_desktop.graves g on g.owner_id=l.owner_id and g.workspace_id=l.workspace_id and g.id=l.grave_id left join demo_desktop.customers c on c.owner_id=g.owner_id and c.workspace_id=g.workspace_id and c.id=g.customer_id where l.report_id=b.id and l.owner_id=p_owner and l.workspace_id=p_workspace and nullif(g.data->>'deleted_at','') is null and (g.customer_id is null or (c.id is not null and nullif(c.data->>'deleted_at','') is null and coalesce(c.data->>'registration_status','registered')<>'declined')) and not exists(select from demo_desktop.privacy_subjects x where x.owner_id=l.owner_id and x.workspace_id=l.workspace_id and (x.customer_id=l.customer_id or l.grave_id=any(x.grave_ids))));
  media_state:=case when affected and not shared then 'retired' when affected or not known or not shared then 'review' else 'active' end;
  insert into demo_desktop.privacy_media(owner_id,workspace_id,kind,asset_id,operation_id,state,record_sha256,photos)
  values(p_owner,p_workspace,'report',b.id,case when media_state<>'active' then p_operation end,media_state,demo_desktop.financial_digest(jsonb_build_object('id',b.id,'photos',b.photos,'location',b.location,'reporterId',b.reporter_id)),(select coalesce(jsonb_agg(jsonb_build_object('id',p->'id','size',p->'size')),'[]') from jsonb_array_elements(b.photos) p))
  on conflict(owner_id,workspace_id,kind,asset_id) do update set operation_id=coalesce(demo_desktop.privacy_media.operation_id,excluded.operation_id),state=case when demo_desktop.privacy_media.state in ('deleting','cleaned') then demo_desktop.privacy_media.state else excluded.state end,photos=case when demo_desktop.privacy_media.state in ('deleting','cleaned') then demo_desktop.privacy_media.photos else excluded.photos end,eligible_at=case when excluded.state<>'active' and demo_desktop.privacy_media.state='active' then clock_timestamp()+interval '6 minutes' else demo_desktop.privacy_media.eligible_at end,version=demo_desktop.privacy_media.version+1;
  if affected and not shared then
   update demo_desktop.privacy_media set retirement_reason='customer' where owner_id=p_owner and workspace_id=p_workspace and kind='report' and asset_id=b.id;
   if exists(select from demo_desktop.privacy_media where owner_id=p_owner and workspace_id=p_workspace and kind='report' and asset_id=b.id and state='cleaned') then delete from public.demo_work_reports where owner_id=p_owner and workspace_id=p_workspace and id=b.id;end if;
  end if;
  if p_operation is not null and media_state<>'active' then
   insert into demo_desktop.privacy_cleanup_jobs(operation_id,owner_id,workspace_id,kind,target_key,state,reason_code) values(p_operation,p_owner,p_workspace,'report',b.id::text,'blocked',case when media_state='review' then 'reference-review' else 'policy-review' end) on conflict do nothing;
  end if;
 end loop;
 if p_operation is not null then delete from public.demo_location_requests where owner_id=p_owner and workspace_id=p_workspace and grave_id=any(s.grave_ids);end if;
end $$;
create or replace function demo_desktop.report_visible(p_owner uuid,p_workspace uuid,p_report uuid) returns boolean language sql stable set search_path='' as $$
 select not demo_desktop.privacy_enabled(p_owner,p_workspace) or (
  not exists(select from demo_desktop.report_work_links l join demo_desktop.privacy_subjects x on x.owner_id=l.owner_id and x.workspace_id=l.workspace_id and (x.customer_id=l.customer_id or l.grave_id=any(x.grave_ids)) where l.report_id=p_report and l.owner_id=p_owner and l.workspace_id=p_workspace)
  and not exists(select from demo_desktop.report_work_links l where l.report_id=p_report and l.owner_id=p_owner and l.workspace_id=p_workspace and not exists(select from demo_desktop.graves g left join demo_desktop.customers c on c.owner_id=g.owner_id and c.workspace_id=g.workspace_id and c.id=g.customer_id where g.owner_id=l.owner_id and g.workspace_id=l.workspace_id and g.id=l.grave_id and nullif(g.data->>'deleted_at','') is null and (g.customer_id is null or (c.id=l.customer_id and nullif(c.data->>'deleted_at','') is null and coalesce(c.data->>'registration_status','registered')<>'declined'))))
  and
  (not exists(select from public.demo_work_reports where owner_id=p_owner and workspace_id=p_workspace and id=p_report) or exists(select from demo_desktop.privacy_media where owner_id=p_owner and workspace_id=p_workspace and kind='report' and asset_id=p_report and (state='active' or retirement_reason='replacement')))
  and not exists(select from public.demo_events e join demo_desktop.privacy_subjects s on s.owner_id=e.owner_id and s.workspace_id=e.workspace_id where e.owner_id=p_owner and e.workspace_id=p_workspace and e.kind='claim_created' and e.payload->>'reportId'=p_report::text and ((e.payload->>'customerId')::bigint=s.customer_id or (e.payload->>'graveId')::bigint=any(s.grave_ids)))
  and not exists(select from public.demo_events e where e.owner_id=p_owner and e.workspace_id=p_workspace and e.kind='claim_created' and e.payload->>'reportId'=p_report::text and not exists(select from demo_desktop.customers c where c.owner_id=p_owner and c.workspace_id=p_workspace and c.id=(e.payload->>'customerId')::bigint and nullif(c.data->>'deleted_at','') is null and coalesce(c.data->>'registration_status','registered')<>'declined' and (e.payload->>'graveId' is null or exists(select from demo_desktop.graves g where g.owner_id=p_owner and g.workspace_id=p_workspace and g.id=(e.payload->>'graveId')::bigint and g.customer_id=c.id and nullif(g.data->>'deleted_at','') is null))))
 )
$$;
revoke all on function demo_desktop.register_private_media(uuid,uuid,uuid),demo_desktop.report_visible(uuid,uuid,uuid) from public,anon,authenticated,service_role;

-- Management overview uses current assignments and exact work/report links.
create index if not exists report_work_progress on demo_desktop.report_work_links(owner_id,workspace_id,work_key,grave_id);
create or replace function public.demo_desktop_work_progress(p_workspace uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);c jsonb;a demo_desktop.work_allocations;ordered jsonb;row_value jsonb;source_row jsonb;report public.demo_work_reports;items jsonb;members jsonb;result jsonb:='[]';done_count integer;total_count integer;begin
 perform demo_desktop.assert_schema();
 perform 1 from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 perform demo_desktop.lock_actor(p_workspace,o);
 c:=demo_desktop.allocation_catalog(o,p_workspace);
 for a in select * from demo_desktop.work_allocations where owner_id=o and workspace_id=p_workspace and jsonb_array_length(data->'userIds')>0 order by data->>'title',id loop
  ordered:=demo_desktop.allocation_rows(c,a.data->'workKeys');items:='[]';done_count:=0;
  select coalesce(jsonb_agg(jsonb_build_object('userId',u.value,'displayName',coalesce(m.display_name,'삭제된 계정'),'active',coalesce(m.active,false)) order by u.pos),'[]') into members from jsonb_array_elements_text(a.data->'userIds') with ordinality u(value,pos) left join public.demo_members m on m.user_id::text=u.value and m.owner_id=o and m.workspace_id=p_workspace;
  for row_value in select value from jsonb_array_elements(ordered) loop
   select value into source_row from jsonb_array_elements(c->'workRows') where value->>'key'=row_value->>'key';
   select r.* into report from public.demo_work_reports r join demo_desktop.report_work_links l on l.report_id=r.id and l.owner_id=r.owner_id and l.workspace_id=r.workspace_id
    where r.owner_id=o and r.workspace_id=p_workspace and r.state='ready' and l.work_key=row_value->>'key' and l.grave_id::text=source_row->>'graveId' and l.customer_id::text is not distinct from source_row->>'customerId' and demo_desktop.report_visible(o,p_workspace,r.id)
    order by r.published_at desc,r.id desc limit 1;
   if report.id is not null then done_count:=done_count+1;end if;
   items:=items||jsonb_build_array(row_value||jsonb_build_object('report',case when report.id is null then null else demo_desktop.report_view(report) end));
  end loop;
  total_count:=jsonb_array_length(ordered);
  result:=result||jsonb_build_array(jsonb_build_object('id',a.id,'title',a.data->'title','year',a.data->'year','version',a.version,'workKeys',a.data->'workKeys','rows',items,'assignees',members,'total',total_count,'completed',done_count,'remaining',total_count-done_count,'outdated',coalesce((a.data->>'outdated')::boolean,false) or a.data->>'rowHash' is distinct from md5(ordered::text) or (a.data->'shared'='false'::jsonb and not exists(select from jsonb_array_elements(coalesce(c->'workSheets','[]')) x where x->>'id'=a.id::text and x->'version'=a.data->'routeVersion' and x->'valid'='true'::jsonb)) or (a.data->'shared'='true'::jsonb and not exists(select from demo_desktop.work_routes x where x.owner_id=o and x.workspace_id=p_workspace and x.id=a.id and x.version=(a.data->>'routeVersion')::bigint and x.data->'basis' is not distinct from demo_desktop.route_basis(o,p_workspace,x.year,x.data->>'regionFilter')))));
 end loop;
 return jsonb_build_object('sheets',result);
end $$;
revoke all on function public.demo_desktop_work_progress(uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_work_progress(uuid) to authenticated;

create or replace function demo_desktop.privacy_row(p_kind text,p jsonb) returns jsonb language plpgsql immutable set search_path='' as $$declare r jsonb;fields jsonb:='{"customers":["id","name","phone","phone_raw","phone_ok","memo","special_notes","registration_status","deleted_at","created_at"],"graves":["id","customer_id","address","gubun","seq","contract_year","gisu","pyeong","note","is_managed","business_region","is_active","deleted_at","created_at"],"payments":["id","grave_id","year","amount","kind","paid_at","method","source","note"],"annualWork":["id","year","customer_id","grave_id","status","notes","deadline","version","deleted_at","origin"],"workRows":["key","customerId","graveId","serviceYear","sequence","number","address","gisu","name","notes","deadline","region","rowNumber","status","deleted_at"],"locations":["id","address","lookupAddress","location"],"location":["lat","lng","source","requestId","requestSeq","accuracy","measuredAt","requesterName","pnu","matchedAddress","datasetDate","fetchedAt","expiresAt"],"earthLinks":["graveId","versionId","summary"],"earthVersions":["versionId","graveId","manifest","state","uploadedAt"]}'::jsonb;begin
 r:=demo_desktop.allowed_json(p,array(select jsonb_array_elements_text(fields->p_kind)));
 if p_kind='payments' and r ? 'source' and r->>'source' not in ('desktop','desktop_sales','sent_claim','legacy_import') then r:=jsonb_set(r,'{source}','"legacy_import"'::jsonb);end if;
 if p_kind='locations' and p ? 'location' then r:=r||jsonb_build_object('location',case when p->'location'='null'::jsonb then 'null'::jsonb else demo_desktop.allowed_json(p->'location',array(select jsonb_array_elements_text(fields->'location'))) end);end if;
 if p_kind='annualWork' and r ? 'origin' and (jsonb_typeof(r->'origin') is distinct from 'string' or r->>'origin' not in ('','registration')) then r:=r-'origin';end if;
 return r;
end $$;

-- Append-only successor: historical frozen SQL files remain unchanged.
-- Persist the creation path rather than guessing from dates or contact status.
create or replace function demo_desktop.register(p_owner uuid,p_workspace uuid,p_input jsonb) returns jsonb
language plpgsql set search_path='' as $$declare v jsonb;cid bigint;gid bigint;y integer;amount bigint;year_now integer:=extract(year from clock_timestamp() at time zone 'Asia/Seoul');candidate record;status text:=coalesce(p_input->>'registrationStatus','registered');phone text;begin
 if p_input-array['type','values','registrationStatus','preparationId']<>'{}' or status not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
 v:=demo_desktop.registration_values(p_input->'values');
 if not exists(select from jsonb_each(v) where value<>'null'::jsonb and (key<>'isManaged' or value='1'::jsonb)) then perform demo_desktop.fail('invalid-input');end if;
 if p_input ? 'preparationId' then
 select * into candidate from demo_desktop.earth_candidates where owner_id=p_owner and workspace_id=p_workspace and id=(p_input->>'preparationId')::uuid and actor_id=auth.uid() and state='prepared' and target->'newCustomer'='true'::jsonb;
 if not found then perform demo_desktop.fail('conflict');end if;cid:=candidate.customer_id;gid:=candidate.grave_id;
 else cid:=demo_desktop.next_id(p_owner,p_workspace,'customers');gid:=demo_desktop.next_id(p_owner,p_workspace,'graves');end if;phone:=nullif(regexp_replace(v->>'phone','[^0-9]','','g'),'');
 insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(p_owner,p_workspace,cid,jsonb_build_object('name',v->'name','phone',phone,'phone_raw',v->'phone','phone_ok',case when v->>'phone' is null or phone~'^0[0-9]{8,10}$' then 1 else 0 end,'memo',v->'requirements','special_notes',v->'specialNotes','registration_status',status,'deleted_at',null,'created_at',clock_timestamp()::text));
 insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(p_owner,p_workspace,gid,cid,jsonb_build_object('address',v->'address','gisu',v->'gisu','pyeong',v->'pyeong','is_managed',coalesce(v->'isManaged','0'::jsonb),'business_region',v->'businessRegion','is_active',1,'deleted_at',null,'created_at',clock_timestamp()::text));
 for y in 2023..2026 loop
  amount:=(v->>('amount'||y))::bigint;
  if y=year_now and v->>'amount' is not null then
   if amount is not null and amount<>(v->>'amount')::bigint then perform demo_desktop.fail('invalid-input');end if;amount:=(v->>'amount')::bigint;
  end if;
  if amount is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,y,'annual',amount,'desktop');end if;
 end loop;
 if year_now not between 2023 and 2026 and v->>'amount' is not null then perform demo_desktop.write_payment(p_owner,p_workspace,gid,year_now,'annual',(v->>'amount')::bigint,'desktop');end if;
 if status='registered' then insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,data) values(p_owner,p_workspace,gen_random_uuid(),year_now,cid,gid,'proceed',jsonb_build_object('notes',coalesce(v->>'specialNotes',''),'deadline','','origin','registration'));end if;
 if p_input ? 'preparationId' then perform demo_desktop.connect_earth(p_owner,p_workspace,null,p_input,true);end if;
 return jsonb_build_object('customerId',cid,'graveId',gid);
end $$;

create or replace function demo_desktop.transfer_payload(p_value jsonb) returns jsonb language plpgsql immutable set search_path='' as $$declare k text;v jsonb;n jsonb;item record;allowed jsonb:='{"customers":["id","name","phone","phone_raw","phone_ok","memo","special_notes","registration_status","deleted_at","created_at"],"graves":["id","customer_id","address","gubun","seq","contract_year","gisu","pyeong","note","is_managed","business_region","is_active","deleted_at","created_at"],"payments":["id","grave_id","year","amount","kind","paid_at","method","source","note"],"annualWork":["id","year","customer_id","grave_id","status","notes","deadline","version","deleted_at","origin"],"workRows":["key","customerId","graveId","serviceYear","sequence","number","address","gisu","name","notes","deadline","region","rowNumber","status","deleted_at"],"locations":["id","address","lookupAddress","location"],"location":["lat","lng","source","requestId","requestSeq","accuracy","measuredAt","requesterName","pnu","matchedAddress","datasetDate","fetchedAt","expiresAt"],"earthLinks":["graveId","versionId","summary"],"earthVersions":["versionId","graveId","manifest","state","uploadedAt"]}'::jsonb;begin
 perform demo_desktop.transfer_keys(p_value,array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','idCounters','events']);
 foreach k in array array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','events'] loop
  if jsonb_typeof(p_value->k) is distinct from 'array' or jsonb_array_length(p_value->k)>100000 then perform demo_desktop.fail('invalid-input');end if;
  for v in select value from jsonb_array_elements(p_value->k) loop
   if k='events' then perform demo_desktop.transfer_keys(v,array['id','workspaceId','kind','at','payload']);continue;end if;
   perform demo_desktop.transfer_keys(v,array(select jsonb_array_elements_text(allowed->k)));
   for item in select * from jsonb_each(v) loop
    if item.key in ('location','summary','manifest') then continue;end if;
    if jsonb_typeof(item.value) not in ('string','number','null') then perform demo_desktop.fail('invalid-input');end if;
   end loop;
   if k='annualWork' and v ? 'origin' and (jsonb_typeof(v->'origin') is distinct from 'string' or v->>'origin' not in ('','registration')) then perform demo_desktop.fail('invalid-input');end if;
   if k='graves' then
    if v ? 'is_managed' and v->'is_managed' not in ('0'::jsonb,'1'::jsonb) then perform demo_desktop.fail('invalid-input');end if;
    if v->>'business_region' is not null and (jsonb_typeof(v->'business_region') is distinct from 'string' or length(v->>'business_region')>100 or v->>'business_region' ~ '[[:cntrl:]]') then perform demo_desktop.fail('invalid-input');end if;
   end if;
   if k='payments' and v->>'source' is not null and v->>'source' not in ('desktop','desktop_sales','sent_claim','legacy_import') then perform demo_desktop.fail('invalid-input');end if;
   if k='locations' and v->'location' is not null and v->'location'<>'null' then
    n:=v->'location';perform demo_desktop.transfer_keys(n,array(select jsonb_array_elements_text(allowed->'location')));
    if jsonb_typeof(n->'lat') is distinct from 'number' or jsonb_typeof(n->'lng') is distinct from 'number' or abs((n->>'lat')::numeric)>90 or abs((n->>'lng')::numeric)>180 then perform demo_desktop.fail('invalid-input');end if;
    if exists(select from jsonb_each(n) x where jsonb_typeof(x.value) not in ('string','number','null')) then perform demo_desktop.fail('invalid-input');end if;
   end if;
   if k='earthLinks' then
    n:=v->'summary';perform demo_desktop.transfer_keys(n,array['source','originalAddress','confirmedAt','name','sourceFile','geometry','point','areaM2','asset']);
    perform demo_desktop.transfer_scalars(n,array['geometry','point','asset']);
    if n ? 'point' then perform demo_desktop.transfer_keys(n->'point',array['lat','lng']);perform demo_desktop.transfer_scalars(n->'point');end if;
    if n ? 'asset' then perform demo_desktop.transfer_keys(n->'asset',array['versionId','sha256','size','sourceFile','state']);perform demo_desktop.transfer_scalars(n->'asset');end if;
    if n ? 'geometry' then perform demo_desktop.transfer_geometry(n->'geometry');end if;
   end if;
   if k='earthVersions' then
    n:=v->'manifest';perform demo_desktop.transfer_keys(n,array['format','schemaVersion','versionId','workspaceId','graveId','originalAddress','importedAt','sourceFile','sha256','size','selection']);
    perform demo_desktop.transfer_scalars(n,array['selection']);
    perform demo_desktop.transfer_keys(n->'selection',array['name','geometry','point','areaM2']);
    perform demo_desktop.transfer_scalars(n->'selection',array['geometry','point']);
    perform demo_desktop.transfer_geometry(n->'selection'->'geometry');
    perform demo_desktop.transfer_keys(n->'selection'->'point',array['lat','lng']);
    perform demo_desktop.transfer_scalars(n->'selection'->'point');
   end if;
  end loop;
 end loop;
 perform demo_desktop.transfer_keys(p_value->'idCounters',array['customers','graves','payments']);
 return p_value;
end $$;

create or replace function demo_desktop.import_legacy(p_workspace uuid,p_request uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);a uuid:=auth.uid();source jsonb;row_value jsonb;previous demo_desktop.requests;fingerprint text;result jsonb;server_revision text;k text;maximum bigint;counter bigint;cid bigint;gid bigint;event_value public.demo_events;begin
 if a<>o then perform demo_desktop.fail('access-denied');end if;
 if p_request is null or jsonb_typeof(p_input) is distinct from 'object' or p_input-array['sourceJson','sourceSha256','serverRevision']<>'{}' or jsonb_typeof(p_input->'sourceJson') is distinct from 'string' or octet_length(p_input->>'sourceJson')>20000000 or coalesce(p_input->>'sourceSha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_input->'serverRevision') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
 if encode(sha256(convert_to(p_input->>'sourceJson','UTF8')),'hex')<>p_input->>'sourceSha256' then perform demo_desktop.fail('source-mismatch');end if;
 begin source:=(p_input->>'sourceJson')::jsonb;exception when others then perform demo_desktop.fail('invalid-input');end;
 if jsonb_typeof(source) is distinct from 'object' or source-array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','idCounters','events']<>'{}' or jsonb_typeof(source->'idCounters') is distinct from 'object' then perform demo_desktop.fail('invalid-input');end if;
 foreach k in array array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','events'] loop if jsonb_typeof(source->k) is distinct from 'array' then perform demo_desktop.fail('invalid-input');end if;end loop;
 select revision into server_revision from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 perform demo_desktop.lock_actor(p_workspace,o);
 fingerprint:=encode(sha256(convert_to('import:'||p_input::text,'UTF8')),'hex');
 select * into previous from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=a and request_id=p_request;
 if found then
  if previous.input_sha<>fingerprint then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'result',previous.result,'snapshot',demo_desktop.snapshot(o,p_workspace));
 end if;
 if exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active) then perform demo_desktop.fail('already-shared');end if;
 if server_revision is distinct from p_input->>'serverRevision' then perform demo_desktop.fail('conflict');end if;
 insert into demo_desktop.companies(owner_id,workspace_id,active,source_revision,source_sha256) values(o,p_workspace,false,server_revision,p_input->>'sourceSha256') on conflict(owner_id,workspace_id) do update set source_revision=excluded.source_revision,source_sha256=excluded.source_sha256;
 if exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace) or exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace) then perform demo_desktop.fail('conflict');end if;
 for row_value in select value from jsonb_array_elements(source->'customers') loop
  cid:=demo_desktop.import_id(row_value,'id');
  if row_value-array['id','name','phone','phone_raw','phone_ok','memo','special_notes','registration_status','deleted_at','created_at']<>'{}' or coalesce(row_value->>'registration_status','registered') not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(o,p_workspace,cid,row_value-'id');
 end loop;
 for row_value in select value from jsonb_array_elements(source->'graves') loop
  gid:=demo_desktop.import_id(row_value,'id');cid:=case when row_value->>'customer_id' is not null then demo_desktop.import_id(row_value,'customer_id') end;
  if row_value-array['id','customer_id','address','gubun','seq','contract_year','gisu','pyeong','note','is_managed','business_region','extra_json','is_active','source_row','deleted_at','created_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(o,p_workspace,gid,cid,row_value-array['id','customer_id']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'payments') loop
  if row_value-array['id','grave_id','year','amount','kind','paid_at','method','source','note']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.payments(owner_id,workspace_id,id,grave_id,year,kind,amount,data) values(o,p_workspace,demo_desktop.import_id(row_value,'id'),demo_desktop.import_id(row_value,'grave_id'),(row_value->>'year')::integer,row_value->>'kind',(row_value->>'amount')::bigint,row_value-array['id','grave_id','year','kind','amount']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'annualWork') loop
  if row_value-array['id','year','customer_id','grave_id','status','notes','deadline','version','deleted_at','origin']<>'{}' or (row_value ? 'origin' and (jsonb_typeof(row_value->'origin') is distinct from 'string' or row_value->>'origin' not in ('','registration'))) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'grave_id' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'grave_id')::bigint and customer_id=(row_value->>'customer_id')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,version,deleted_at,data) values(o,p_workspace,(row_value->>'id')::uuid,(row_value->>'year')::integer,demo_desktop.import_id(row_value,'customer_id'),case when row_value->>'grave_id' is not null then demo_desktop.import_id(row_value,'grave_id') end,row_value->>'status',coalesce((row_value->>'version')::bigint,1),row_value->>'deleted_at',row_value-array['id','year','customer_id','grave_id','status','version','deleted_at']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'workRows') loop
  if coalesce(row_value->>'key','')='' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'customerId' is not null and not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=(row_value->>'customerId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'graveId' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint and (row_value->>'customerId' is null or customer_id=(row_value->>'customerId')::bigint)) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.work_rows values(o,p_workspace,row_value->>'key',row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'locations') loop insert into demo_desktop.locations values(o,p_workspace,demo_desktop.import_id(row_value,'id'),row_value);end loop;
 for row_value in select value from jsonb_array_elements(source->'earthVersions') loop
  if row_value->'manifest'->>'workspaceId' is distinct from p_workspace::text or row_value->'manifest'->>'versionId' is distinct from row_value->>'versionId' or row_value->'manifest'->>'graveId' is distinct from row_value->>'graveId' or not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.imported_earth_versions values(o,p_workspace,(row_value->>'versionId')::uuid,demo_desktop.import_id(row_value,'graveId'),row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'earthLinks') loop
  if row_value->>'versionId' is not null and not exists(select from demo_desktop.imported_earth_versions where owner_id=o and workspace_id=p_workspace and version_id=(row_value->>'versionId')::uuid and grave_id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'versionId' is not null then
   if not exists(select from public.demo_earth_assets a join demo_desktop.imported_earth_versions v on v.owner_id=a.owner_id and v.workspace_id=a.workspace_id and v.version_id=a.version_id where a.owner_id=o and a.workspace_id=p_workspace and a.version_id=(row_value->>'versionId')::uuid and a.state='ready' and a.retired_at is null and a.manifest=v.data->'manifest') then perform demo_desktop.fail('earth-not-ready');end if;
   row_value:=jsonb_set(row_value,'{summary,asset}',(select jsonb_build_object('versionId',v.version_id,'sha256',v.data->'manifest'->'sha256','size',v.data->'manifest'->'size','sourceFile',v.data->'manifest'->'sourceFile','state','ready') from demo_desktop.imported_earth_versions v where v.owner_id=o and v.workspace_id=p_workspace and v.version_id=(row_value->>'versionId')::uuid));
  end if;
  insert into demo_desktop.earth_links values(o,p_workspace,demo_desktop.import_id(row_value,'graveId'),(row_value->>'versionId')::uuid,row_value->'summary');
 end loop;
 foreach k in array array['customers','graves','payments'] loop
  execute format('select coalesce(max(id),0) from demo_desktop.%I where owner_id=$1 and workspace_id=$2',k) into maximum using o,p_workspace;
  if jsonb_typeof(source->'idCounters'->k) is distinct from 'number' or (source->'idCounters'->>k)::numeric<>trunc((source->'idCounters'->>k)::numeric) then perform demo_desktop.fail('invalid-input');end if;
  counter:=(source->'idCounters'->>k)::bigint;if counter<maximum or counter>9007199254740991 then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.id_counters values(o,p_workspace,k,counter) on conflict(owner_id,workspace_id,name) do update set high_water=greatest(demo_desktop.id_counters.high_water,excluded.high_water);
 end loop;
 -- Events remain additive and keep their original IDs. Current customer changes never rewrite history.
 for row_value in select value from jsonb_array_elements(source->'events') order by case value->>'kind' when 'claim_created' then 0 else 1 end,value->>'at',value->>'id' loop
  if row_value->>'workspaceId' is distinct from p_workspace::text then perform demo_desktop.fail('invalid-input');end if;
  select * into event_value from public.demo_events where owner_id=o and id=(row_value->>'id')::uuid;
  if found then
   if event_value.workspace_id<>p_workspace or event_value.kind is distinct from row_value->>'kind' or event_value.payload is distinct from row_value->'payload' or event_value.happened_at is distinct from (row_value->>'at')::timestamptz then perform demo_desktop.fail('conflict');end if;
  else insert into public.demo_events(owner_id,workspace_id,id,kind,happened_at,payload) values(o,p_workspace,(row_value->>'id')::uuid,row_value->>'kind',(row_value->>'at')::timestamptz,row_value->'payload');end if;
 end loop;
 update demo_desktop.companies set active=true where owner_id=o and workspace_id=p_workspace;
 if to_regprocedure('demo_desktop.refresh_sent_amounts(uuid,uuid)') is not null then perform demo_desktop.refresh_sent_amounts(o,p_workspace);end if;
 perform demo_desktop.refresh_projection(o,p_workspace);
 result:=jsonb_build_object('imported',true,'sourceSha256',p_input->>'sourceSha256','serverRevision',p_input->>'serverRevision');
 insert into demo_desktop.requests values(o,p_workspace,a,p_request,gen_random_uuid(),fingerprint,result,clock_timestamp());
 return jsonb_build_object('requestId',p_request,'result',result,'snapshot',demo_desktop.snapshot(o,p_workspace));
end $$;

create or replace function demo_desktop.import_transfer(p_workspace uuid,p_request uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);a uuid:=auth.uid();source jsonb;row_value jsonb;previous demo_desktop.requests;fingerprint text;result jsonb;server_revision text;k text;maximum bigint;counter bigint;cid bigint;gid bigint;event_value public.demo_events;begin
 if a<>o then perform demo_desktop.fail('access-denied');end if;
 if p_request is null or jsonb_typeof(p_input) is distinct from 'object' or p_input-array['protocol','sourceSha256','transferSha256','transferJson','serverRevision']<>'{}' or p_input->>'protocol' is distinct from '2' or jsonb_typeof(p_input->'transferJson') is distinct from 'string' or octet_length(p_input->>'transferJson')>20000000 or coalesce(p_input->>'sourceSha256','')!~'^[a-f0-9]{64}$' or coalesce(p_input->>'transferSha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_input->'serverRevision') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
 if encode(sha256(convert_to(p_input->>'transferJson','UTF8')),'hex')<>p_input->>'transferSha256' then perform demo_desktop.fail('source-mismatch');end if;
 begin source:=(p_input->>'transferJson')::jsonb;exception when others then perform demo_desktop.fail('invalid-input');end;
 source:=demo_desktop.transfer_payload(source);
 select revision into server_revision from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 perform demo_desktop.lock_actor(p_workspace,o);
 fingerprint:=encode(sha256(convert_to('import:'||p_input::text,'UTF8')),'hex');
 select * into previous from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=a and request_id=p_request;
 if found then
  if previous.input_sha<>fingerprint then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'result',previous.result,'snapshot',demo_desktop.snapshot(o,p_workspace));
 end if;
 if exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active) then perform demo_desktop.fail('already-shared');end if;
 if server_revision is distinct from p_input->>'serverRevision' then perform demo_desktop.fail('conflict');end if;
 insert into demo_desktop.companies(owner_id,workspace_id,active,source_revision,source_sha256) values(o,p_workspace,false,server_revision,p_input->>'sourceSha256') on conflict(owner_id,workspace_id) do update set source_revision=excluded.source_revision,source_sha256=excluded.source_sha256;
 if exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace) or exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace) then perform demo_desktop.fail('conflict');end if;
 for row_value in select value from jsonb_array_elements(source->'customers') loop
  cid:=demo_desktop.import_id(row_value,'id');
  if row_value-array['id','name','phone','phone_raw','phone_ok','memo','special_notes','registration_status','deleted_at','created_at']<>'{}' or coalesce(row_value->>'registration_status','registered') not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(o,p_workspace,cid,row_value-'id');
 end loop;
 for row_value in select value from jsonb_array_elements(source->'graves') loop
  gid:=demo_desktop.import_id(row_value,'id');cid:=case when row_value->>'customer_id' is not null then demo_desktop.import_id(row_value,'customer_id') end;
  if row_value-array['id','customer_id','address','gubun','seq','contract_year','gisu','pyeong','note','is_managed','business_region','is_active','deleted_at','created_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(o,p_workspace,gid,cid,row_value-array['id','customer_id']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'payments') loop
  if row_value-array['id','grave_id','year','amount','kind','paid_at','method','source','note']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.payments(owner_id,workspace_id,id,grave_id,year,kind,amount,data) values(o,p_workspace,demo_desktop.import_id(row_value,'id'),demo_desktop.import_id(row_value,'grave_id'),(row_value->>'year')::integer,row_value->>'kind',(row_value->>'amount')::bigint,row_value-array['id','grave_id','year','kind','amount']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'annualWork') loop
  if row_value-array['id','year','customer_id','grave_id','status','notes','deadline','version','deleted_at','origin']<>'{}' or (row_value ? 'origin' and (jsonb_typeof(row_value->'origin') is distinct from 'string' or row_value->>'origin' not in ('','registration'))) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'grave_id' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'grave_id')::bigint and customer_id=(row_value->>'customer_id')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,version,deleted_at,data) values(o,p_workspace,(row_value->>'id')::uuid,(row_value->>'year')::integer,demo_desktop.import_id(row_value,'customer_id'),case when row_value->>'grave_id' is not null then demo_desktop.import_id(row_value,'grave_id') end,row_value->>'status',coalesce((row_value->>'version')::bigint,1),row_value->>'deleted_at',row_value-array['id','year','customer_id','grave_id','status','version','deleted_at']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'workRows') loop
  if coalesce(row_value->>'key','')='' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'customerId' is not null and not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=(row_value->>'customerId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'graveId' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint and (row_value->>'customerId' is null or customer_id=(row_value->>'customerId')::bigint)) then perform demo_desktop.fail('invalid-input');end if;
